  // Converts flat Supabase cash_positions rows back to the rich banks-object format
  const convertSbCashPos=(raw)=>{
    const out={};
    Object.entries(raw).forEach(([date,c])=>{
      out[date]=c.banks?c:{
        ...emptyDayPosition(date),
        banks:{
          bpi:      {beg:String(c.bpi_beg||0),      book:String(c.bpi_book||0),      end:String(c.bpi_end||0)},
          metro:    {beg:String(c.metrobank_beg||0), book:String(c.metrobank_book||0),end:String(c.metrobank_end||0)},
          china:    {beg:String(c.chinabank_beg||0), book:String(c.chinabank_book||0),end:String(c.chinabank_end||0)},
          bdo:      {beg:String(c.bdo_beg||0),       book:String(c.bdo_book||0),      end:String(c.bdo_end||0)},
          security: {beg:String(c.secbank_beg||0),   book:String(c.secbank_book||0),  end:String(c.secbank_end||0)},
          union:    {beg:String(c.unionbank_beg||0),  book:String(c.unionbank_book||0), end:String(c.unionbank_end||0)},
        },
        collections:{
          fabhubAmt:0,
          approvedPayments: typeof c.approved_payments==="string"?(()=>{try{return JSON.parse(c.approved_payments||"[]");}catch(e){return[];}})():(c.approved_payments||[]),
          manualCollections: typeof c.manual_collections==="string"?(()=>{try{return JSON.parse(c.manual_collections||"[]");}catch(e){return[];}})():(c.manual_collections||[]),
        },
        disbursements:{
          manual: typeof c.manual_disbursements==="string"?(()=>{try{return JSON.parse(c.manual_disbursements||"[]");}catch(e){return[];}})():(c.manual_disbursements||[]),
        },
        floatingChecks: typeof c.floating_checks==="string"?(()=>{try{return JSON.parse(c.floating_checks||"[]");}catch(e){return[];}})():(c.floating_checks||[]),
        audit: typeof c.audit==="string"?(()=>{try{return JSON.parse(c.audit||"[]");}catch(e){return[];}})():(c.audit||[]),
        transactions:typeof c.transactions==='string'?(()=>{try{return JSON.parse(c.transactions||'[]');}catch(e){return[];}})():(c.transactions||[]),
        ytd:{
          supplierPayable:c.ytd_supplier_payable>0?String(c.ytd_supplier_payable):"",
          loansPayable:   c.ytd_loans_payable>0?String(c.ytd_loans_payable):"",
          accountsReceivable:"",
          expectedCollection:"",
        },
        notes:c.notes||"",
        savedAt:c.updated_at||null,
      };
    });
    return out;
  };

  // ── SUPABASE FIELD MAPPERS (camelCase → snake_case) ─────────────────────────
  const toSbDeal = r=>({
    id:r.id, ce_no:r.ceNo, client:r.client, contact:r.contact,
    ce_type:r.ceType, product:r.product, stage:r.stage,
    priority:r.priority||"Normal", sales_owner:r.salesOwner||"",
    biz_dev_source:r.bizDevSource||"", lead_origin:leadOriginOf(r), date_acquired:r.dateAcquired||null,
    due_date:r.dueDate||null, follow_up:r.followUp||null,
    value:Number(r.value)||0,
    invoiced:Number(r.invoiced)||0, amount_paid:Number(r.amountPaid)||0,
    payment_status:r.paymentStatus||"Unpaid", receipt_type:r.receiptType||null,
    withholding:r.withholding||false, comms_group:r.commsGroup||"",
    sales_repo_link:r.salesRepoLink||"", proposal_folder_link:r.proposalFolderLink||"",
    notes:r.notes||"", probability:Number(r.probability)||0,
    location:r.location||"",
    added_by:r.addedBy||"", added_at:r.addedAt||null,
    award_request_data:r.awardRequestData||null,
    parent_deal_id:r.parentDealId||null,
    standby_po:!!r.standbyPO, po_budget:r.standbyPO?(Number(r.poBudget)||0):0,
    billing_generated:r.billingGenerated||false,
    // Receivables policy §2.1 onboarding facts + §2.3/§3 satisfaction
    bir_2303_url:r.bir2303Url||null, bir_2303_on_file:!!r.bir2303OnFile,
    vat_treatment:r.vatTreatment||null,
    downpayment_pct:r.downpaymentPct!=null&&r.downpaymentPct!==""?Number(r.downpaymentPct):null,
    payment_terms_text:r.paymentTermsText||null,
    client_satisfied:!!r.clientSatisfied, satisfaction_note:r.satisfactionNote||null,
    updated_at:new Date().toISOString(),
  });
  const toSbJO = r=>({
    id:r.id, deal_id:r.dealId, jo_no:r.joNo||r.joNum||"",
    client:r.client||"", ce_no:r.ceNo||"", project_name:r.projectName||r.contact||"",
    value:Number(r.value)||0, award_trigger:r.awardTrigger||"",
    trigger_date:r.triggerDate||null, trigger_note:r.triggerNote||"",
    pm1:r.pm1||"", pm2:r.pm2||"", pm3:r.pm3||"", coordinator:r.coordinator||"",
    ae_assigned:r.aeAssigned||"", start_date:r.startDate||null,
    comms_link:r.commsLink||"", scope_notes:r.scopeNotes||"",
    special_instructions:r.specialInstructions||"",
    designer:r.designer||"",
    location:r.location||"",
    budget_status:r.budgetStatus||"QS Budget Pending",
    status:r.status||"Active", issued_date:r.issuedDate||r.dateIssued||null,
  });
  const toSbBilling = r=>{
    // A milestone with no receipt type of its own inherits its deal's — so the
    // persisted vat/ewt/net_receivable follow the deal form (e.g. an AR / VAT-
    // exempt addendum) instead of silently defaulting to OR and baking in 12% VAT.
    const od=deals.find(d=>d.id===r.dealId);
    const tx=calcTax(Number(r.amount)||0,r.receiptType??od?.receiptType??"OR",r.withholding??od?.withholding??false);
    const base={
      id:r.id, deal_id:r.dealId, name:r.name||"", description:r.description||"",
      amount:Number(r.amount)||0, invoice_no:r.invoiceNo||"",
      invoice_date:r.invoiceDate||null, due_date:r.dueDate||null,
      sent_date:r.sentDate||null,
      status:r.status||"Draft", created_by:r.createdBy||"",
      receipt_type:r.receiptType||null, withholding:r.withholding??null,
      vat:tx.vat, ewt:tx.ewt, net_receivable:tx.netReceivable,
    };
    // Retention columns only when set, so writes work before supabase_retention.sql
    // runs (the retry queue syncs them once the columns exist).
    if(r.retentionHeld!=null) base.retention_held=Number(r.retentionHeld)||0;
    if(r.isRetentionRelease) base.is_retention_release=true;
    return base;
  };
  const toSbPayment = r=>({
    id:r.id, milestone_id:r.milestoneId, amount:Number(r.amount)||0,
    date:r.date||null, ref_no:r.refNo||"", note:r.note||"",
    recorded_by:r.recordedBy||"", bank:r.bank||"",
    value_date:r.valueDate||null,
    payment_method:r.method||"", bounced:!!r.bounced,
  });
  const toSbExpense = r=>{
    let date=r.expDate||null;
    if(!date){const yr=r.year||new Date().getFullYear();const mo=r.month!=null?Number(r.month):new Date().getMonth();date=`${yr}-${String(mo+1).padStart(2,'0')}-01`;}
    const desc=r.note||r.description||"";
    const base={id:r.id,deal_id:r.dealId||r.projectId||null,date,
      category:r.category||"",description:desc,note:desc,
      amount:Number(r.amount)||0,supplier:r.payee||r.supplier||"",receipt_no:r.receiptNo||"",
      bank_account:r.bankAccount||null,cleared_date:r.clearedDate||null,
      acct_status:r.acctStatus||"Logged",payment_method:r.paymentMethod||"",
      payable_id:r.payableId||null,cv_id:r.cvId||null,
      routed_by:r.routedBy||"",routed_at:r.routedAt||null,
      qty:Number(r.qty)||1,price_per_qty:Number(r.pricePerQty)||0,
      tin:r.tin||"",remarks:r.remarks||"",account_code:r.accountCode||null};
    // Tax columns only included when the expense is tax-tagged, so writes keep
    // working before supabase_input_tax.sql is applied (the retry queue syncs
    // any tax-tagged expense once the columns exist).
    if(r.vatable!=null){
      base.vatable=!!r.vatable;
      base.input_vat=Number(r.inputVat)||0;
      base.ewt_rate=Number(r.ewtRate)||0;
      base.ewt_amount=Number(r.ewtAmount)||0;
      base.net_amount=Number(r.netAmount)||0;
    }
    return base;
  };
  const toSbPR = r=>{
    const uuidRe=/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
    const rawId=r.projectId||r.dealId||null;
    const dealId=(rawId==="__gmd_stocks__")?null:(rawId&&uuidRe.test(rawId)?rawId:null);
    return({
    id:r.id, deal_id:dealId, item:r.itemName||r.item||"",
    supplier:r.supplier||"", qty:Number(r.qty)||0, unit:r.unit||"",
    estimated_cost:Number(r.estUnitCost||r.estimatedCost)||0,
    actual_cost:Number(r.actUnitCost||r.actualCost)||0,
    budget_category:r.budgetCategory||"", status:r.status||"Pending Approval",
    qty_delivered:Number(r.qtyDelivered)||0, delivery_date:r.deliveryDate||null,
    dr_no:r.drNo||"", notes:r.notes||"", created_by:r.createdBy||r.requestedBy||"",
    po_number:r.poNumber||"", po_date:r.poDate||null,
    delivery_note:r.deliveryNote||"", requested_by:r.requestedBy||"",
    approved_by:r.approvedBy||"", project_name:r.projectName||"",
    with_vat:r.withVat||false,
    from_mr_id:r.fromMrId||null,
    urgency:r.urgency||"Normal",
    approved_at:r.approvedAt||null,
    delivery_history:r.deliveryHistory?JSON.stringify(r.deliveryHistory):null,
    acct_status:r.acctStatus||"", acct_notes:r.acctNotes||"",
    acct_checked_by:r.acctCheckedBy||"", acct_checked_at:r.acctCheckedAt||null,
    payment_bank:r.paymentBank||"", payment_ref:r.paymentRef||"",
    payment_ordered_by:r.paymentOrderedBy||"", payment_ordered_at:r.paymentOrderedAt||null,
    paid_ref:r.paidRef||"", paid_date:r.paidDate||null,
    paid_amt:r.paidAmt!=null?Number(r.paidAmt):null, paid_by:r.paidBy||"",
    disc_type:r.discType||"none", disc_value:Number(r.discValue)||0,
    po_discount_type:r.poDiscType||"none", po_discount_value:Number(r.poDiscValue)||0,
    account_code:r.accountCode||"",
  });};
  const toSbMR = r=>{const uuidRe=/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;const rawId=r.projectId||r.dealId||null;const dealId=rawId&&uuidRe.test(rawId)?rawId:null;return({
    id:r.id, deal_id:dealId,
    item:r.itemName||r.item||"", category:r.category||"",
    qty:Number(r.qty)||0, unit:r.unit||"",
    estimated_cost:Number(r.estUnitCost||r.estimatedCost)||0,
    urgency:r.urgency||"Normal", purpose:r.purpose||"", notes:r.notes||"",
    status:r.status||"Submitted", submitted_by:r.requestedBy||r.submittedBy||"",
    created_by:r.createdBy||r.requestedBy||r.submittedBy||"",
    status_changed_at:r.statusChangedAt||null,
  });};
  const toSbBR = r=>{const uuidRe=/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;const rawId=r.projectId||r.dealId||null;const dealId=rawId&&uuidRe.test(rawId)?rawId:null;return({
    id:r.id, deal_id:dealId, purpose:r.purpose||"",
    title:r.title||r.purpose||"",
    amount:Number(r.amount)||0, urgency:r.urgency||"Normal",
    date_needed:r.dateNeeded||null, status:r.status||"Pending",
    approved_by:r.approvedBy||"", submitted_by:r.requestedBy||r.submittedBy||"",
    category:r.category||"", notes:r.notes||"",
    released_by:r.releasedBy||"", released_at:r.releasedAt||null,
    status_changed_at:r.statusChangedAt||null,
  });};
  const toSbAddendum = r=>({
    id:r.id, deal_id:r.dealId||r.projectId, title:r.title||"", description:r.description||r.desc||"",
    value:Number(r.value)||0, ce_no:r.ceNo||"",
    kind:r.kind||"Additive", scope_items:Array.isArray(r.scopeItems)?r.scopeItems:[],
    receipt_type:r.receiptType||"OR", withholding:r.withholding||false,
    cost_impact:Number(r.costImpact||r.value)||0,
    status:r.status||"Discovered", sales_notified:r.salesNotified||false,
    discovered_by:r.discoveredBy||"", client_approved:r.clientApproved||false,
    co_boq_data:r.coBoqData||null,
    sales_owner:r.salesOwner||null, awarded_date:r.awardedDate||null, sub_account:r.subAccount||null,
  });
  const toSbSwatch = r=>({
    id:r.id, deal_id:r.dealId||r.projectId||null, name:r.name||"", category:r.category||"",
    qty:Number(r.qty)||0, unit:r.unit||"", supplier:r.supplier||"",
    ref_link:r.refLink||r.swatchLink||"", status:r.status||"To Buy", notes:r.notes||"",
    est_cost:Number(r.estCost)||0, swatch_link:r.swatchLink||r.refLink||"",
    added_by:r.addedBy||"",
    client_approved_by:r.clientApprovedBy||null,
    client_approved_at:r.clientApprovedAt||null,
  });
  const toSbChecklist = r=>({
    id:r.id, deal_id:r.dealId||r.projectId||null, type:r.type||"Task", title:r.title||"",
    description:r.description||"", status:r.status||"Pending",
    assigned_to:r.assignedTo||"", due_date:r.dueDate||null,
    risk_note:r.riskNote||"", sort_order:r.sortOrder||0,
    dept:r.dept||"", priority:r.priority||"Normal",
    notes:r.notes||"", supplier:r.supplier||"",
    created_by:r.createdBy||"", what_could_go_wrong:r.whatCouldGoWrong||"",
    qty:Number(r.qty)||0, unit:r.unit||"pcs",
    category:r.category||null, location:r.location||null,
  });
  const toSbUser = u=>({
    id:u.id, name:u.name||"", username:u.username||"", role:u.role||"Sales",
    title:u.title||"", status:u.status||"active", password_hash:u.passwordHash||"",
    email:u.email||"", created_at:u.createdAt||null,
  });
  const toSbBudget = (dealId,b)=>({
    deal_id:dealId, materials:Number(b.Materials)||0, labor:Number(b.Labor)||0,
    overhead:Number(b.Overhead)||0, subcon:Number(b.Subcon)||0, notes:b.notes||"",
    set_by:b.setBy||"",
  });
  const toSbActivity = r=>({
    id:r.id||("act"+Date.now()), deal_id:r.dealId||null,
    action:r.action||"", detail:r.detail||"",
    by:r.by||"", date:r.date||today, time:r.time||"",
  });

  // ── SUPABASE SYNC HELPERS ─────────────────────────────────────────────────
  // Fire-and-forget — never blocks the UI. Errors logged to console only.
  const isUUID=s=>/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(String(s||''));
  // Reject payloads where any UUID-typed column holds a non-UUID value (old numeric IDs).
  const hasValidUUIDs=p=>(!p.id||isUUID(p.id))&&(!p.deal_id||isUUID(p.deal_id))&&(!p.milestone_id||isUUID(p.milestone_id))&&(!p.card_id||isUUID(p.card_id));
  const sbSync=(table,records,mapper)=>{
    if(!isSupabaseReady()||!records?.length) return;
    Promise.all(records.map(r=>{
      const payload=mapper?mapper(r):r;
      if(!hasValidUUIDs(payload)) return Promise.resolve();
      return sbUpsert(table,payload,'id');
    })).catch(e=>console.error("FabHub sbSync "+table+":",e.message));
  };
  // Returns the sbUpsert outcome (true/false) so a caller that's about to write
  // a DEPENDENT row (one referencing this record by foreign key) can await
  // confirmation first — see createProjectCard for why this matters.
  // Client-side mirror of the server INSERT policies (supabase_migration_037_
  // rls_rollout_v2.sql). Its ONLY job is to keep the bulk/auto re-push paths
  // (migrateToCloud + the load-time auto-sync) from re-uploading records the
  // current role can't write. Those pushes replay the whole local cache — most
  // of which was synced DOWN from the server — so for a role not in a table's
  // insert list, RLS rejects every row with "new row violates row-level
  // security policy". The drop handler then paints that as "N changes NOT saved
  // — please redo them", which is both alarming and wrong: the rows already
  // exist on the server and nothing was lost (observed live: 53 job_orders =
  // the entire table). Skipping the doomed writes removes the false alarm
  // without weakening RLS — the server stays the source of truth, and any
  // genuine single-record write still goes through its own guarded path.
  // Aliases match the mint-session ROLE_MAP so raw profile roles map to the
  // canonical RLS roles before the check. Tables absent from the map are left
  // unrestricted so no legitimate push path changes behavior.
  const INSERT_ROLES={
    deals:["Manager","Sales","SalesOpsAdmin"],
    job_orders:["Manager","ProjectMover"],
    purchase_requests:["Manager","Finance","FinanceAssistant","Procurement"],
    material_requests:["Manager","Sales","Procurement","SalesOpsAdmin"],
    budget_requests:["Manager","Sales","Procurement","SalesOpsAdmin"],
    subcon_work_orders:["Manager","Finance","FinanceAssistant","Procurement"],
    addenda:["Manager","ProjectMover","Procurement","Design"],
    swatches:["Manager","Procurement","Design"],
    // checklists: intentionally UNMAPPED. Migration 049 opened checklists
    // INSERT/UPDATE to any logged-in user (AUTH); leaving it out of this map
    // means roleCanInsert returns true, matching the server. (Previously listed
    // Manager/ProjectMover only, which wrongly blocked the bulk-sync push for
    // Sales/Design/Finance even though RLS now allows them.)
    expenses:["Manager","Finance","Accounting","FinanceAssistant"],
    billing_milestones:["Manager","Finance","FinanceAssistant","SalesOpsAdmin"],
    billing_payments:["Manager","Finance","FinanceAssistant","SalesOpsAdmin"],
    commission_payouts:["Manager","Finance","FinanceAssistant"],
    project_budgets:["Manager","QS"],
    // activity_log is INSERT=AUTH server-side — any logged-in user may write it.
  };
  const ROLE_ALIASES={Operations:"ProjectMover",Ops:"ProjectMover","Cost Control":"Finance",Admin:"Manager"};
  const roleCanInsert=(table)=>{
    const allowed=INSERT_ROLES[table];
    if(!allowed) return true; // unmapped table → don't change push behavior
    const canon=ROLE_ALIASES[role]||role;
    return allowed.includes(canon);
  };
  // ── Permission guard for user-initiated writes ──────────────────────────────
  // Checks the PERMISSIONS map (client mirror of RLS) BEFORE a role-gated write
  // and, if the current role isn't allowed, shows a clear dialog and returns
  // false so the caller can abort — instead of optimistically changing local
  // state that the next server resync silently reverts. Used at the write sites
  // where RLS is stricter than the UI (addendum status, daily-log/calendar
  // deletes). Unmapped tables/actions are allowed, so this never over-blocks.
  const roleCanDo=(action,table)=>roleCan(ROLE_ALIASES[role]||role,action,table);
  const guardWrite=async(action,table,label)=>{
    if(roleCanDo(action,table)) return true;
    const verb={select:"view",insert:"add",update:"edit",delete:"delete"}[action]||action;
    await uiAlert({
      title:"Not allowed for your role",
      message:`Your role (${roleLabel(role)}) can't ${verb} ${label||table}.\n\nThis is limited to: ${rolesAllowedLabel(action,table)}.\n\nNothing was changed. Ask a manager if you need access.`,
      tone:"warning",
    });
    return false;
  };
  const sbSyncOne=(table,record,mapper)=>{
    if(!isSupabaseReady()||!record) return Promise.resolve(false);
    // Don't re-push what RLS will reject — see roleCanInsert / INSERT_ROLES above.
    if(!roleCanInsert(table)) return Promise.resolve(false);
    const payload=mapper?mapper(record):record;
    if(!hasValidUUIDs(payload)) return Promise.resolve(false);
    return sbUpsert(table,payload,'id')
      .catch(e=>{console.error("FabHub sbSyncOne "+table+":",e.message);return false;});
  };
  const sbSyncDelete=(table,id)=>{
    if(!isSupabaseReady()||!id) return;
    sbDelete(table,id).catch(e=>console.error("FabHub sbDelete "+table+":",e.message));
  };

  // ── PERSIST — updates the save indicator; Supabase is the write target ──
  // ── PERSIST — updates save indicator; Supabase is the write target ──
  const persist=useCallback((_key,_val)=>{
    setSync("saving");
    idbSetMany([[_key,_val]]).then(()=>setSync("saved")).catch(()=>setSync("saved"));
  },[]);

  const upUsers    =useCallback(fn=>setUsers(p=>{const n=fn(p);persist(KEYS.users,n);return n;}),[persist]);
  const upCashPos  =useCallback(fn=>setCashPos(p=>{const n=fn(p);persist(KEYS.cashPos,n);return n;}),[persist]);
  const upEvouchers=useCallback(fn=>setEvouchers(p=>{const n=fn(p);persist(KEYS.evouchers,n);if(isSupabaseReady())sbUpsert('app_settings',{key:'evouchers',value:n,updated_at:new Date().toISOString()},'key').catch(()=>{});return n;}),[persist]);
  // EV/LQ numbers used local max+1 with no server-side atomicity — the same
  // cross-device collision risk already fixed for PO/CV/JO/CE.
  const addEV=async(ev)=>{
    const evNo=await claimEvNo(`EV-${new Date().getFullYear()}-000`,evouchers.map(e=>e.evNo));
    const lqNo=await claimDocNumber("LQ",evouchers.map(e=>e.lqNo),6);
    const ne={...ev,id:uid(),evNo,lqNo,status:ev.status||"Draft",createdBy:session?.name||"",createdAt:new Date().toISOString(),items:ev.items||[]};
    upEvouchers(es=>[...es,ne]);
  };
  const updateEV=(id,ch)=>upEvouchers(es=>es.map(e=>e.id===id?{...e,...ch}:e));
  const deleteEV=(id)=>upEvouchers(es=>es.filter(e=>e.id!==id));
  const addEVItem=(evId,item)=>upEvouchers(es=>es.map(e=>e.id===evId?{...e,items:[...(e.items||[]),{...item,id:uid()}]}:e));
  const updateEVItem=(evId,itemId,ch)=>upEvouchers(es=>es.map(e=>e.id===evId?{...e,items:(e.items||[]).map(i=>i.id===itemId?{...i,...ch}:i)}:e));
  // Liquidation line items are the one financial delete in the app that had no
  // confirmation and no trace afterward (evouchers is outside FIN_AUDIT, whose
  // archive/restore is built for whole table rows, not items nested inside a
  // record) — at minimum, gate it and leave a trail in the activity log.
  const deleteEVItem=async (evId,itemId)=>{
    const ev=evouchers.find(e=>e.id===evId);
    const item=ev?.items?.find(i=>i.id===itemId);
    if(item&&!(await uiConfirm(`Delete this liquidation item?\n\n${item.description||"Item"} — ₱${Number(item.amount||0).toLocaleString("en-PH")}\n\nThis cannot be undone.`))) return;
    upEvouchers(es=>es.map(e=>e.id===evId?{...e,items:(e.items||[]).filter(i=>i.id!==itemId)}:e));
    if(item) logActivity(ev?.dealId||null,"EV Item Deleted",`Liquidation item removed from ${ev?.evNo||evId}: ${item.description||"item"} (₱${Number(item.amount||0).toLocaleString("en-PH")})`,session?.name);
  };
  const submitEV=(id)=>upEvouchers(es=>es.map(e=>e.id===id?{...e,status:"For Payment",submittedAt:new Date().toISOString()}:e));
  const markEVPaid=(id,bank,ref)=>upEvouchers(es=>es.map(e=>e.id===id?{...e,status:"Paid",paidBank:bank,paidRef:ref,paidAt:new Date().toISOString(),paidBy:session?.name||"Finance"}:e));
  // Activity log helper — called whenever something meaningful happens
  const logActivity=(dealId,action,detail,by)=>{
    const entry={id:uid(),dealId,action,detail,by:by||session?.name||"System",date:today,time:new Date().toLocaleTimeString("en-PH",{hour:"2-digit",minute:"2-digit"})};
    setActLog(prev=>{const next=[entry,...prev].slice(0,500);return next;});
    if(isSupabaseReady()) sbInsert('activity_log',toSbActivity(entry)).catch(()=>{});
    if(action==="PM Update"){
      const deal=deals.find(d=>d.id===dealId);
      sendTelegramNotification("ops",`📝 <b>PM Update</b>\n${deal?.client||dealId}\nBy: ${entry.by} · ${today}\n${detail||""}`);
    }
  };
  const upPcards    =useCallback(fn=>setPcards(p=>{const n=fn(p);persist(KEYS.pcards,n);return n;}),[persist]);

  // ── FINANCIAL AUDIT TRAIL (soft-delete) ───────────────────────────────────
  // Money records are never silently lost: before an expense, check voucher,
  // payable, loan, loan payment, cash inflow or billing collection is deleted
  // we snapshot the row (in its Supabase shape) into audit_log with who / when
  // / why, so it appears in Finance ▸ Audit Trail and can be restored.
  const inflowToSb=r=>({id:r.id,deal_id:r.dealId||r.projectId||null,date:r.date||r.month||null,amount:Number(r.amount)||0,source:r.source||"",ref_no:r.refNo||"",note:r.note||""});
  const FIN_AUDIT={
    expenses:       {label:"expense",          toSb:toSbExpense},
    check_vouchers: {label:"check voucher",    toSb:cvToSb},
    payables:       {label:"payable",          toSb:payableToSb},
    loans:          {label:"loan",             toSb:loanToSb},
    loan_payments:  {label:"loan payment",     toSb:r=>({id:r.id,loan_id:r.loanId||r.loan_id||null,amount:Number(r.amount)||0,date:r.date||null})},
    inflows:        {label:"cash inflow",      toSb:inflowToSb},
    billing_payments:{label:"collection",     toSb:r=>toSbPayment(r)},
    billing_milestones:{label:"billing milestone", toSb:toSbBilling},
  };
  // Write to audit_log via the raw client (not sbInsert) so a missing-table /
  // audit-only failure doesn't trip the app-wide "you're offline" warning.
  const writeAudit=async(entry)=>{
    if(!supabase) return;
    try{ const {error}=await supabase.from("audit_log").insert(entry); if(error) console.error("audit_log:",error.message); }
    catch(e){ console.error("audit_log:",e.message); }
  };
  const archiveFinancial=async(table,sbSnapshot,recordId,reason)=>{
    const entry={id:uid(),table_name:table,record_id:String(recordId??""),action:"delete",snapshot:sbSnapshot||null,reason:reason||"",performed_by:session?.name||role||"System",performed_at:new Date().toISOString()};
    await writeAudit(entry);
    return entry;
  };
  // Prompt for a reason, archive the record, then return true to proceed with the delete.
  const confirmFinancialDelete=async(table,record)=>{
    const cfg=FIN_AUDIT[table]||{};
    if(!record) return true; // nothing to snapshot — shouldn't happen, don't block
    const reason=(await uiPrompt(`Delete this ${cfg.label||"financial record"}?\n\nIt will be archived in Finance ▸ Audit Trail and can be restored.\nReason (required):`,""));
    if(reason===null) return false;                 // cancelled
    if(!reason.trim()){ toastEmit("A reason is required to delete a financial record.","error",5000); return false; }
    const snap=cfg.toSb?cfg.toSb(record):record;
    await archiveFinancial(table,snap,record.id,reason.trim());
    logActivity(record.dealId||record.projectId||null,"Financial Record Deleted",`${cfg.label||table} deleted — ${reason.trim()}`);
    return true;
  };
  // Restore a previously-deleted record from its audit snapshot.
  const restoreFinancial=async(audit)=>{
    if(!audit?.snapshot||!audit?.table_name){ toastEmit("Nothing to restore.","error"); return false; }
    if(!isSupabaseReady()){ toastEmit("Restore needs a server connection.","error"); return false; }
    try{
      await sbUpsert(audit.table_name,audit.snapshot,"id");
      await writeAudit({id:uid(),table_name:audit.table_name,record_id:audit.record_id,action:"restore",snapshot:audit.snapshot,reason:"Restored from audit trail",performed_by:session?.name||role||"System",performed_at:new Date().toISOString()});
      logActivity(null,"Financial Record Restored",`${(FIN_AUDIT[audit.table_name]||{}).label||audit.table_name} restored`);
      await loadAllFromSupabase();
      toastEmit("✅ Record restored. (Loan payments & collections may need a refresh to re-link.)","success",6000);
      return true;
    }catch(e){ console.error("restore:",e); toastEmit("Restore failed — see console.","error",6000); return false; }
  };

  // One-time migration: push all IDB-cached data to Supabase on new devices
  const migrateToCloud=useCallback(async()=>{
    if(!isSupabaseReady()){toastEmit("Supabase is not connected — check environment variables","error",5000);return;}
    toastEmit("Pushing all data to cloud…","info",2500);
    // Skip tables the current role can't INSERT (see roleCanInsert): re-pushing
    // them only produces false "NOT saved — please redo" toasts for rows RLS
    // rejects, which already exist on the server.
    const syncAll=(table,arr,mapper)=>(arr?.length&&roleCanInsert(table))?Promise.all(arr.map(r=>{const p=mapper?mapper(r):r;return hasValidUUIDs(p)?sbUpsert(table,p,'id'):Promise.resolve();})).catch(e=>console.error("migrate "+table+":",e.message)):Promise.resolve();
    await syncAll("deals",deals,toSbDeal);
    await syncAll("job_orders",jos,toSbJO);
    await syncAll("expenses",exps,toSbExpense);
    await syncAll("purchase_requests",prs,toSbPR);
    await syncAll("subcon_work_orders",swos,swoToSb);
    await syncAll("material_requests",mreqs,toSbMR);
    await syncAll("budget_requests",breqs,toSbBR);
    await syncAll("addenda",addenda,toSbAddendum);
    await syncAll("swatches",swatches,toSbSwatch);
    await syncAll("checklists",checklist,toSbChecklist);
    await syncAll("activity_log",actLog,toSbActivity);
    if(billings?.length){
      await Promise.all(billings.map(m=>{if(!isUUID(m.id))return Promise.resolve();sbSyncOne("billing_milestones",m,toSbBilling);return Promise.all((m.payments||[]).map(p=>isUUID(p.id)?sbSyncOne("billing_payments",{...p,milestoneId:m.id},toSbPayment):Promise.resolve()));})).catch(()=>{});
    }
    if(budgets&&roleCanInsert("project_budgets")){Object.entries(budgets).forEach(([dealId,b])=>{if(isUUID(dealId)) sbUpsert("project_budgets",toSbBudget(dealId,b),"deal_id").catch(()=>{});});}
        manual_collections: JSON.stringify(pos.collections?.manualCollections||[]),
    setTimeout(()=>toastEmit("Done! All data pushed to Supabase. Refresh Safari to see it.","success",6000),1200);
  },[hasValidUUIDs,deals,jos,exps,prs,mreqs,breqs,addenda,swatches,checklist,actLog,billings,budgets,cashPositions,infs]);
  const upInventory =useCallback(fn=>setInventory(p=>{const n=fn(p);persist(KEYS.inventory,n);return n;}),[persist]);
  const upStocklog  =useCallback(fn=>setStocklog(p=>{const n=fn(p);persist(KEYS.stocklog,n);return n;}),[persist]);
  const upTools     =useCallback(fn=>setTools(p=>{const n=fn(p);persist(KEYS.tools,n);return n;}),[persist]);
  const upDrs       =useCallback(fn=>setDrs(p=>{const n=fn(p);persist(KEYS.drs,n);return n;}),[persist]);
  const upSuppliers =useCallback(fn=>setSuppliers(p=>{const n=fn(p);persist(KEYS.suppliers,n);return n;}),[persist]);
  const upSubcons   =useCallback(fn=>setSubcons(p=>{const n=fn(p);persist(KEYS.subcons,n);return n;}),[persist]);
  const upSwos      =useCallback(fn=>setSwos(p=>{const n=fn(p);persist(KEYS.swos,n);return n;}),[persist]);

  const addInventoryItem=(item)=>upInventory(iv=>{
    const rec={...item,id:item.id||uid(),code:item.code||nextItemCode(iv),createdAt:today,createdBy:session?.name||role};
    if(isSupabaseReady()) sbUpsert('inventory_items',invToSb(rec),'id').catch(e=>console.warn("inv insert:",e.message));
    return[...iv,rec];
  });
  const updateInventoryItem=(id,ch)=>{
    upInventory(iv=>iv.map(i=>i.id===id?{...i,...ch,lastUpdated:today}:i));
    if(isSupabaseReady()) sbUpdate('inventory_items',id,invToSb({...ch,lastUpdated:today})).catch(()=>{});
  };
  const deleteInventoryItem=(id)=>{
    upInventory(iv=>iv.filter(i=>i.id!==id));
    if(isSupabaseReady()) sbDelete('inventory_items',id).catch(()=>{});
  };
  // Wipe ALL inventory items and stock movements — local + Supabase. Used to start fresh.
  const clearAllInventory=async()=>{
    upInventory(()=>[]);
    upStocklog(()=>[]);
    if(isSupabaseReady()){
      try{ await sbClear('stock_movements'); await sbClear('inventory_items'); }
      catch(e){ toastEmit&&toastEmit("Cleared locally but server wipe failed: "+(e?.message||e),"error"); return false; }
    }
    return true;
  };

  // Merge duplicate inventory items into one survivor: reassign every stock
  // movement from the duplicates to the survivor, fold their on-hand qty and
  // value into the survivor (weighted avg cost), then delete the duplicates.
  // Local + Supabase. Returns the number of duplicates merged.
  const mergeInventoryItems=(survivorId,dupeIds=[])=>{
    const ids=dupeIds.filter(d=>d&&d!==survivorId);
    if(!survivorId||!ids.length) return 0;
    const idSet=new Set(ids);
    // 1) reassign movements
    upStocklog(sl=>sl.map(m=>{
      if(!idSet.has(m.itemId)) return m;
      if(isSupabaseReady()&&isUUID(m.id)) sbUpdate('stock_movements',m.id,{item_id:survivorId}).catch(()=>{});
      return {...m,itemId:survivorId};
    }));
    // 2) fold qty + value into survivor, 3) drop duplicates
    upInventory(iv=>{
      const survivor=iv.find(i=>i.id===survivorId); if(!survivor) return iv;
      const dupes=iv.filter(i=>idSet.has(i.id));
      let totQty=Number(survivor.qtyOnHand)||0, totVal=(Number(survivor.qtyOnHand)||0)*(Number(survivor.avgCost)||0);
      dupes.forEach(d=>{const q=Number(d.qtyOnHand)||0;totQty+=q;totVal+=q*(Number(d.avgCost)||Number(d.lastPurchasePrice)||0);});
      const merged={...survivor,qtyOnHand:Math.round(totQty*100)/100,avgCost:totQty>0?Math.round((totVal/totQty)*100)/100:survivor.avgCost,lastUpdated:today};
      if(isSupabaseReady()){
        sbUpdate('inventory_items',survivorId,invToSb(merged)).catch(()=>{});
        ids.forEach(id=>sbDelete('inventory_items',id).catch(()=>{}));
      }
      return iv.filter(i=>!idSet.has(i.id)).map(i=>i.id===survivorId?merged:i);
    });
    return ids.length;
  };

  // Tools / equipment register CRUD (local + Supabase)
  const saveTool=(rec)=>{
    const r={...rec,id:rec.id||uid()};
    upTools(ts=>ts.some(t=>t.id===r.id)?ts.map(t=>t.id===r.id?r:t):[r,...ts]);
    if(isSupabaseReady()) sbUpsert('tools',toolToSb(r),'id').catch(()=>{});
    return r;
  };
  const deleteTool=(id)=>{
    upTools(ts=>ts.filter(t=>t.id!==id));
    if(isSupabaseReady()) sbDelete('tools',id).catch(()=>{});
  };
  // Standalone delivery-receipt CRUD (local + Supabase)
  const saveDr=(rec)=>{
    const r={...rec,id:rec.id||uid(),createdBy:rec.createdBy||session?.name||role,createdAt:rec.createdAt||today};
    upDrs(ds=>ds.some(d=>d.id===r.id)?ds.map(d=>d.id===r.id?r:d):[r,...ds]);
    if(isSupabaseReady()) sbUpsert('delivery_receipts',drToSb(r),'id').catch(()=>{});
    return r;
  };
  const deleteDr=(id)=>{
    upDrs(ds=>ds.filter(d=>d.id!==id));
    if(isSupabaseReady()) sbDelete('delivery_receipts',id).catch(()=>{});
  };

  // Supplier CRUD
  const addSupplier=(item)=>upSuppliers(ss=>{
    const rec={...item,id:uid(),createdAt:today,createdBy:session?.name||role};
    if(isSupabaseReady()) sbInsert('suppliers',supToSb(rec)).catch(()=>{});
    return[...ss,rec];
  });
  // Typing a not-yet-known supplier/payee name while logging an expense adds it
  // to the Supplier Master so it shows up as a pick next time (mirrors how a
  // typed-in team member name gets remembered for the Project Team roster).
  const rememberSupplierNames=(names)=>{
    const known=new Set(suppliers.map(s=>(s.companyName||"").trim().toLowerCase()).filter(Boolean));
    const fresh=[...new Set(names.map(n=>(n||"").trim()).filter(n=>n&&!known.has(n.toLowerCase())))];
    fresh.forEach(name=>addSupplier({companyName:name,status:"Active"}));
  };
  const updateSupplier=(id,ch)=>{
    upSuppliers(ss=>ss.map(s=>s.id===id?{...s,...ch}:s));
    if(isSupabaseReady()) sbUpdate('suppliers',id,supToSb(ch)).catch(()=>{});
  };
  const deleteSupplier=(id)=>{
    upSuppliers(ss=>ss.filter(s=>s.id!==id));
    if(isSupabaseReady()) sbDelete('suppliers',id).catch(()=>{});
  };
  // Subcontractor CRUD
  const addSubcon=(item)=>upSubcons(ss=>{
    const rec={...item,id:uid(),createdAt:today,createdBy:session?.name||role};
    if(isSupabaseReady()) sbInsert('subcontractors',subconToSb(rec)).catch(()=>{});
    return[...ss,rec];
  });
  const updateSubcon=(id,ch)=>{
    upSubcons(ss=>ss.map(s=>s.id===id?{...s,...ch}:s));
    if(isSupabaseReady()) sbUpdate('subcontractors',id,subconToSb(ch)).catch(()=>{});
  };
  const deleteSubcon=(id)=>{
    upSubcons(ss=>ss.filter(s=>s.id!==id));
    if(isSupabaseReady()) sbDelete('subcontractors',id).catch(()=>{});
  };

  const addSWO=(wo)=>{
    const rec={...wo,id:uid(),createdDate:today};
    upSwos(ws=>[rec,...ws]);
    if(isSupabaseReady()) sbSyncOne("subcon_work_orders",rec,swoToSb);
    syncWoPayable(rec); // WO issued → subcontractor payable in the AP ledger
    const msg=`🛠 <b>${rec.status==="Pending Approval"?"Work Order Awaiting Approval":"Subcon Work Order Issued"} ${rec.woNumber||""}</b>\n${rec.subcontractor||"?"}${rec.specialty?` · ${rec.specialty}`:""}\nProject: ${rec.projectName||"?"}\nAmount: ₱${(Number(rec.contractAmount)||0).toLocaleString("en-PH")}\nBy: ${rec.requestedBy||session?.name||"?"}`;
    sendTelegramNotification("procurement",msg);
    sendTelegramNotification("management",msg);
  };
  // Bulk-create Work Orders from a batch upload. Records arrive fully shaped by
  // the view (status/requestedBy/approvedBy already decided by role), so here we
  // only allocate collision-free WO numbers, persist in ONE state update, mirror
  // each to Supabase + the AP ledger, and fire a single summary notification.
  const addSWOBatch=(list)=>{
    const items=(list||[]).filter(Boolean);
    if(!items.length) return 0;
    const taken=new Set(swos.map(w=>w.woNumber).filter(Boolean));
    let nn=Number(WO_NO_RE.exec(computeNextWoNo(swos))[1]);
    const recs=items.map(wo=>{
      let woNo=(wo.woNumber||"").trim();
      if(!woNo||taken.has(woNo)){
        while(taken.has(`WO-${String(nn).padStart(4,"0")}`)) nn++;
        woNo=`WO-${String(nn).padStart(4,"0")}`; nn++;
      }
      taken.add(woNo);
      return {...wo,woNumber:woNo,id:uid(),createdDate:today};
    });
    upSwos(ws=>[...recs,...ws]);
    if(isSupabaseReady()) recs.forEach(rec=>sbSyncOne("subcon_work_orders",rec,swoToSb));
    recs.forEach(rec=>syncWoPayable(rec));
    const total=recs.reduce((s,r)=>s+(Number(r.contractAmount)||0),0);
    const anyPending=recs.some(r=>r.status==="Pending Approval");
    const msg=`🛠 <b>${recs.length} Subcon Work Order${recs.length>1?"s":""} uploaded${anyPending?" — some awaiting approval":""}</b>\nRange: ${recs[recs.length-1].woNumber} → ${recs[0].woNumber}\nTotal: ₱${total.toLocaleString("en-PH")}\nBy: ${session?.name||"?"}`;
    sendTelegramNotification("procurement",msg);
    sendTelegramNotification("management",msg);
    return recs.length;
  };
  const updateSWO=(id,changes)=>{
    let updated=null;
    upSwos(ws=>ws.map(w=>{
      if(w.id!==id) return w;
      const nw={...w,...changes};
      updated=nw;
      if(isSupabaseReady()) sbSyncOne("subcon_work_orders",nw,swoToSb);
      return nw;
    }));
    if(updated) syncWoPayable(updated); // keep the WO's AP payable in sync (created once it's Issued)
  };
  const deleteSWO=(id)=>{
    const wo=swos.find(w=>w.id===id);
    if(wo&&role!=="Manager"&&role!=="Procurement"&&wo.requestedBy!==session?.name) return toastEmit&&toastEmit("Only Managers, Procurement, or the creator can delete work orders.","error");
    upSwos(ws=>ws.filter(w=>w.id!==id));if(isSupabaseReady()) sbDelete('subcon_work_orders',id).catch(()=>{});
  };

  // addCEReq/updateCEReq used to await the server round-trip before touching
  // local state, while the CEQSView caller showed a hardcoded "Saved" toast
  // regardless of the outcome — on any transient failure (flaky connection,
  // stale session) the CE Request a Sales rep just submitted vanished with no
  // trace: never shown locally, never queued for retry, no error surfaced.
  // Rewritten to the optimistic local-update + background-sync pattern used
  // everywhere else in the app (see addSWO/addDRF) so the record always shows
  // up immediately and failed writes are queued/retried instead of dropped.
  const addCEReq=(rec)=>{
    const nr={...rec,id:rec.id||uid(),created_at:rec.created_at||new Date().toISOString()};
    setCeReqs(p=>[...p,ceReqFromSb(nr)]);
    return isSupabaseReady()?sbUpsert('ce_requests',nr,'id').catch(()=>false):Promise.resolve(true);
  };
  const updateCEReq=(id,updates)=>{
    setCeReqs(p=>p.map(r=>{if(r.id!==id)return r;return{...r,...(updates.status!==undefined?{status:updates.status}:{}),clientName:updates.client_name??r.clientName,projectName:updates.project_name??r.projectName,location:updates.location??r.location,projectType:updates.project_type??r.projectType,priority:updates.priority??r.priority,submittedBy:updates.submitted_by??r.submittedBy,targetDeadline:updates.target_deadline??r.targetDeadline,submissionDeadline:updates.submission_deadline??r.submissionDeadline,targetBudget:updates.target_budget??r.targetBudget,targetMargin:updates.target_margin??r.targetMargin,plansLink:updates.plans_link??r.plansLink,skpLink:updates.skp_link??r.skpLink,scheduleOfFinish:updates.schedule_of_finish??r.scheduleOfFinish,notes:updates.notes??r.notes,ceNotes:updates.ce_notes??r.ceNotes,bidAmount:updates.bid_amount??r.bidAmount,bidMarginPct:updates.bid_margin_pct??r.bidMarginPct,awarded:updates.awarded??r.awarded,awardDate:updates.award_date??r.awardDate};}));
    return isSupabaseReady()?sbUpdate('ce_requests',id,updates).catch(()=>{}):Promise.resolve();
  };
  const deleteCEReq=async(id)=>{
    setCeReqs(p=>p.filter(r=>r.id!==id));
    if(isSupabaseReady()) sbDelete('ce_requests',id).catch(()=>{});
  };

