  const upDrfs   =useCallback(fn=>setDrfs(p=>{const n=fn(p);persist(KEYS.drfs,n);return n;}),[persist]);

  // ── BOT SETTINGS CRUD ────────────────────────────────────────────────────
  const saveBotSettings=async(data)=>{
    const n={...data};
    // Guard: if the form's token field is blank but we already have a token, don't overwrite it
    if(!n.token && botSettings.token) n.token=botSettings.token;
    if(!n.token) n.token=sessionStorage.getItem('fabhub:bottoken')||"";
    setBotSettings(n);
    // Cache token in sessionStorage — survives refresh within same tab, clears on browser close
    if(n.token) sessionStorage.setItem('fabhub:bottoken',n.token);
    // Durably cache the full settings (incl. token) in IndexedDB so the token survives a browser
    // restart even when the Supabase sync below fails (offline / anon auth off / RLS). The load
    // path already restores the token from this IndexedDB cache.
    idbSetMany([[KEYS.botsettings,n]]).catch(()=>{});
    // Store chatIds in localStorage (never the token — intentional security boundary)
    const localSafe={chatIds:n.chatIds,hideValueInBots:n.hideValueInBots};
    localStorage.setItem(KEYS.botsettings,JSON.stringify(localSafe));
    if(isSupabaseReady()){
      try{
        const{data:existing}=await supabase.from('app_settings').select('key').eq('key','botsettings').maybeSingle();
        if(existing){
          const{error}=await supabase.from('app_settings').update({value:n,updated_at:new Date().toISOString()}).eq('key','botsettings');
          if(error) throw error;
        } else {
          const{error}=await supabase.from('app_settings').insert({key:'botsettings',value:n,updated_at:new Date().toISOString()});
          if(error) throw error;
        }
      }catch(e){
        toastEmit("Bot settings saved locally but failed to sync to server: "+(e?.message||e),"error");
      }
    }
  };

  // ── TELEGRAM NOTIFICATION UTILITY ────────────────────────────────────────
  const sendTelegramNotification=useCallback(async(dept,message)=>{
    let token=botSettings.token;
    let ids=botSettings.chatIds;
    // If botSettings not yet hydrated (race with Supabase load), fetch live
    if(!token && isSupabaseReady()){
      try{
        const {data:row}=await supabase.from('app_settings').select('value').eq('key','botsettings').single();
        if(row?.value?.token){
          token=row.value.token;
          ids=row.value.chatIds;
          setBotSettings(row.value);
          sessionStorage.setItem('fabhub:bottoken',token);
          localStorage.setItem(KEYS.botsettings,JSON.stringify({chatIds:row.value.chatIds,hideValueInBots:row.value.hideValueInBots}));
        }
      }catch{}
    }
    if(!token) return;
    const chatId=ids?.[dept]||ids?.management;
    if(!chatId) return;
    try{
      await fetch(`https://api.telegram.org/bot${token}/sendMessage`,{
        method:"POST",headers:{"Content-Type":"application/json"},
        body:JSON.stringify({chat_id:chatId,text:message,parse_mode:"HTML"})
      });
    }catch(e){console.warn("Telegram notify failed:",e);}
  },[botSettings]);

  const sendToAllChannels=(message)=>{
    ["general","ops","design","procurement","sales","management"].forEach(dept=>sendTelegramNotification(dept,message));
  };

  const addBlocker=useCallback((dealId,title,dept,detail)=>{
    const entry={id:uid(),dealId,title,dept:dept||"Operations",detail:detail||"",flaggedBy:session?.name||"PM",status:"Open",createdAt:new Date().toISOString(),resolvedBy:null,resolvedAt:null};
    setBlockers(prev=>{const n=[entry,...prev];localStorage.setItem(KEYS.blockers,JSON.stringify(n));idbSetMany([[KEYS.blockers,n]]).catch(()=>{});return n;});
    if(isSupabaseReady()) sbInsert('project_blockers',{id:entry.id,deal_id:dealId,title,dept:dept||"Operations",detail:detail||"",flagged_by:session?.name||"PM",status:"Open",created_at:entry.createdAt}).catch(()=>{});
    logActivity(dealId,"Blocker Flagged",`${title} — needs ${dept}`,session?.name);
    const d=deals.find(x=>x.id===dealId);
    const msg=`⛔ <b>Blocker Flagged</b>\n${d?.client||dealId}\n<b>${title}</b>${detail?"\n"+detail:""}\nFlagged by: ${session?.name} · Dept: ${dept}`;
    const DEPT_CHANNEL={Operations:"ops",Design:"design",Procurement:"procurement","Cost Control":"finance",QS:"management",Sales:"sales",Finance:"finance"};
    const deptKey=DEPT_CHANNEL[dept]||(dept||"").toLowerCase().replace(/[^a-z]/g,"");
    sendTelegramNotification(deptKey,msg);
    sendTelegramNotification("management",msg);
  },[session,deals,logActivity,sendTelegramNotification]);

  const resolveBlocker=useCallback((blockerId)=>{
    setBlockers(prev=>{
      const n=prev.map(b=>b.id===blockerId?{...b,status:"Resolved",resolvedBy:session?.name,resolvedAt:new Date().toISOString()}:b);
      localStorage.setItem(KEYS.blockers,JSON.stringify(n));idbSetMany([[KEYS.blockers,n]]).catch(()=>{});
      const resolved=n.find(b=>b.id===blockerId);
      if(resolved&&isSupabaseReady()) sbUpdate('project_blockers',blockerId,{status:"Resolved",resolved_by:resolved.resolvedBy,resolved_at:resolved.resolvedAt}).catch(()=>{});
      if(resolved){
        const d=deals.find(x=>x.id===resolved.dealId);
        const msg=`✅ <b>Blocker Resolved</b>\n${d?.client||resolved.dealId}\n<b>${resolved.title}</b>\nResolved by: ${session?.name}`;
        sendTelegramNotification("management",msg);
        const DEPT_CHANNEL={Operations:"ops",Design:"design",Procurement:"procurement","Cost Control":"finance",QS:"management",Sales:"sales",Finance:"finance"};
        const dk=DEPT_CHANNEL[resolved.dept]||(resolved.dept||"").toLowerCase().replace(/[^a-z]/g,"");
        sendTelegramNotification(dk,msg);
      }
      return n;
    });
  },[session,deals,sendTelegramNotification]);

  const addDRF=async(drf)=>{
    // Was `DRF-${ds.length+1}` — generated from array LENGTH, so deleting any
    // DRF made the next one reuse a number, on top of the same cross-device
    // collision risk the other doc numbers already had. Atomic counter fixes both.
    const no=await claimDocNumber("DRF",drfs.map(d=>d.drfNo),4,true);
    const rec={...drf,id:uid(),drfNo:no,createdAt:today,status:"New",createdBy:drf.createdBy||session?.name||role};
    upDrfs(ds=>[...ds,rec]);
    sendTelegramNotification("design",`📝 <b>New Design Request</b>\n${no} · ${drf.client||"?"}\nProject: ${drf.projectTitle||"—"}\nDeadline: ${drf.designDeadline||"TBD"}\nBy: ${drf.createdBy||"?"}`);
    if(!isSupabaseReady()) return true;
    const result=await sbInsert('design_requests',drfToSb(rec));
    return !!result;
  };
  const updateDRF=(id,data)=>{
    // Merge the partial `data` onto the existing record BEFORE mapping to
    // Supabase. drfToSb fills every unset column with empty defaults, so
    // passing the raw partial (e.g. just {designer,status} from the assign
    // dropdown) wiped drf_no/client/project_title/design_deadline in the DB —
    // the DRF "got lost" on the next sync. Map the full merged row instead.
    upDrfs(ds=>{
      const next=ds.map(d=>d.id===id?{...d,...data}:d);
      if(isSupabaseReady()){
        const merged=next.find(d=>d.id===id);
        if(merged) sbUpdate('design_requests',id,drfToSb(merged)).catch(()=>{});
      }
      return next;
    });
  };
  const deleteDRF=(id)=>{
    upDrfs(ds=>ds.filter(d=>d.id!==id));
    if(isSupabaseReady()) sbDelete('design_requests',id).catch(()=>{});
  };

  // ── PM Update + Addendum helpers ─────────────────────────────────────────
  // ── Proactive Checklist Template Auto-Load ──────────────────────────────────
  const loadChecklistTemplate=(dealId,clientName)=>{
    // Only load if no checklist items exist for this project yet
    const existing=checklist.filter(c=>(c.projectId||c.dealId)===dealId);
    if(existing.length>0) return; // already has items — don't overwrite
    const items=GMD_CHECKLIST_TEMPLATE.map(t=>({
      ...t,
      id:uid(),
      projectId:dealId,
      title:t.title,
      status:"To Do",
      customType:"",
      assignedTo:"",
      dueDate:"",
      supplier:"",
      qty:"",
      unit:"pcs",
      createdDate:today,
      createdBy:"System (Template)",
    }));
    upChecklist(cs=>[...cs,...items]);
    if(isSupabaseReady()) items.forEach(item=>sbInsert('checklists',toSbChecklist(item)).catch(()=>{}));
  };

  const addPmUpdate=(projId,entryOrText,by)=>{
    const entry=typeof entryOrText==="object"&&entryOrText!==null
      ? entryOrText
      : {id:uid(),type:"General Progress",note:String(entryOrText||""),text:String(entryOrText||""),by:by||session?.name||"Team",date:today,time:new Date().toLocaleTimeString("en-PH",{hour:"2-digit",minute:"2-digit"})};
    if(!(entry.note||entry.text||"").trim()) return;
    upProj(projId,p=>({...p,pmUpdates:[entry,...(p.pmUpdates||[])]}));
    const deal=deals.find(d=>d.id===projId);
    if(entry.type!=="Blocker"&&entry.type!=="Materials Needed"&&entry.type!=="Design Request"){
      sendTelegramNotification("ops",`📝 <b>PM Update — ${deal?.client||projId}</b>\nBy: ${entry.by} · ${today}\n${entry.note||entry.text||""}`);
    }
  };
  const addAddendum=(dealId,title,desc,requestedBy)=>{
    const entry={id:uid(),dealId,title,desc,requestedBy,date:today,status:"Pending",notifiedSales:false,notifiedOps:false};
    upDeals(ds=>ds.map(d=>d.id===dealId?{...d,addenda:[entry,...(d.addenda||[])]}:d));
    upProj(dealId,p=>({...p,addenda:[entry,...(p.addenda||[])]}));
    if(isSupabaseReady()) sbSyncOne("addenda",entry,toSbAddendum);
    const deal=deals.find(d=>d.id===dealId);
    const msg=`⚠️ <b>Scope Change Logged</b>\n${title||"?"}\nProject: ${deal?.client||dealId||"?"}\nBy: ${requestedBy||"?"}\n\n📌 Sales must quote this to client before proceeding.`;
    sendTelegramNotification("sales",msg);
    sendTelegramNotification("ops",msg);
    sendTelegramNotification("procurement",msg);
    sendTelegramNotification("management",msg);
  };
  const updateAddendumStatus=async(dealId,addId,status)=>{
    // Advancing an addendum's status is a Manager-only UPDATE server-side (RLS).
    // Guard first so a PM/Ops user gets a clear dialog instead of a change that
    // reverts on the next resync.
    if(!await guardWrite('update','addenda','a scope change status')) return;
    upDeals(ds=>ds.map(d=>d.id===dealId?{...d,addenda:(d.addenda||[]).map(a=>a.id===addId?{...a,status}:a)}:d));
    if(isSupabaseReady()) sbUpdate('addenda',addId,{status,updated_at:new Date().toISOString()}).catch(()=>{});
  };

  // ── Checklist state ──────────────────────────────────────────────────────────
  const[clModal,   setClModal]  = useState(false);
  const[clForm,    setClForm]   = useState({projectId:null,type:"Task",customType:"",title:"",dept:"Operations",assignedTo:"",status:"To Do",priority:"Normal",dueDate:"",supplier:"",notes:"",whatCouldGoWrong:"",qty:"",unit:"pcs"});
  const[editCl,    setEditCl]   = useState(null);
  const[clProjF,   setClProjF]  = useState("all");
  const[clTypeF,   setClTypeF]  = useState("All");
  const[clStatF,   setClStatF]  = useState("All");
  const[clDeptF,   setClDeptF]  = useState("All");

  const openAddCl=(projId=null,dept="Operations",type="Task")=>{setClForm({projectId:projId,type,customType:"",title:"",dept:dept,assignedTo:"",status:"To Do",priority:"Normal",dueDate:"",supplier:"",notes:"",whatCouldGoWrong:"",qty:"",unit:"pcs"});setEditCl(null);setClModal(true);};
  const openEditCl=item=>{setClForm({...item,customType:CL_TYPES.includes(item.type)?"":item.type,whatCouldGoWrong:item.whatCouldGoWrong||"",qty:item.qty||"",unit:item.unit||"pcs"});setEditCl(item.id);setClModal(true);};
  const saveCl=()=>{
    if(!clForm.title||!clForm.title.trim()){toastEmit("Task title is required.","error");return;}
    if(!clForm.dept){toastEmit("Department is required.","error");return;}
    if(clForm.type==="Custom"&&!clForm.customType?.trim()){toastEmit("Please describe the custom task type.","error");return;}
    const finalType=clForm.type==="Custom"&&clForm.customType?clForm.customType.trim():clForm.type;
    if(!finalType){toastEmit("Task type is required.","error");return;}
    const rec={...clForm,type:finalType,id:editCl||uid(),createdDate:today,createdBy:role};
    upChecklist(cs=>editCl?cs.map(c=>c.id===editCl?rec:c):[...cs,rec]);
    if(isSupabaseReady()) sbSyncOne("checklists",rec,toSbChecklist);
    setClModal(false);setEditCl(null);
  };
  const delCl=delChecklist;
  const clStatusQ=(id,st)=>{
    upChecklist(cs=>cs.map(c=>c.id===id?{...c,status:st}:c));
    if(isSupabaseReady()) sbUpdate('checklists',id,{status:st}).catch(e=>{toastEmit("Task status sync failed — check connection.","warning");console.error("clStatusQ:",e);});
    if(st==="Done") toastEmit("Task marked done!","success");
  };

  // ── Auth helpers ───────────────────────────────────────────────────────────
  const login=async(username,password)=>{
    const unameLower=username.toLowerCase().trim();
    const defUser=DEFAULT_USERS.find(x=>x.username===unameLower);
    let u=null, viaServer=false, needsUpgrade=false;
    // Verify the password server-side via the verify_login RPC — the hash
    // comparison happens in Postgres, so the actual password_hash never has to
    // be read into the browser (previously fetched via select('*') and
    // compared client-side, which — combined with RLS being open to `anon` —
    // let anyone with the public anon key bulk-read every user's hash with no
    // login at all). Falls back to the old local/DEFAULT_USERS check only if
    // Supabase is unreachable (offline / pre-load / RPC not yet applied).
    if(isSupabaseReady()){
      try{
        // mint-session verifies the password in Postgres and returns a signed,
        // role-bearing token (stored by appLogin) that RLS uses for every request.
        const{user,error}=await appLogin(unameLower,password);
        if(user){
          viaServer=true;
          u={id:user.id,username:user.username,name:user.name,role:user.role,title:user.title||user.role,status:user.status};
          needsUpgrade=!!user.needs_upgrade;
        } else if(error && !defUser){
          return error;   // server rejected credentials and no built-in default to fall back to
        }
        // else: rejected but a DEFAULT_USERS entry exists → fall through to the local check
      }catch(e){ /* network/offline → fall back to local/default check below */ }
    }
    if(!viaServer){
      let localU=users.find(x=>x.username.toLowerCase()===unameLower);
      if(!localU&&defUser) localU={...defUser,status:"active"};
      if(!localU) return "Username not found.";
      if(localU.status==="pending") return "Your account is pending approval by a Manager.";
      if(localU.status==="inactive") return "Your account has been deactivated. Contact Paulo.";
      const hashToCheck=localU.passwordHash||(defUser?.passwordHash||"");
      let valid=hashToCheck?await checkPw(password,hashToCheck,localU.username):false;
      if(!valid&&defUser) valid=await checkPw(password,defUser.passwordHash,localU.username);
      if(!valid) return "Incorrect password.";
      needsUpgrade=!hashToCheck.startsWith("sha256:");
      u=localU;
    }
    if(!u) return "Username not found.";
    if(u.status==="pending") return "Your account is pending approval by a Manager.";
    if(u.status==="inactive") return "Your account has been deactivated. Contact Paulo.";
    // Auto-upgrade legacy btoa hash to SHA-256 on successful login
    if(needsUpgrade){
      const newHash=await sha256Hash(password,u.username);
      const upgraded={...u,passwordHash:newHash};
      upUsers(us=>us.map(x=>x.id===u.id?upgraded:x));
      if(isSupabaseReady()) sbUpsert('user_profiles',toSbUser(upgraded),'id').catch(()=>{});
    }
    const sess={userId:u.id,username:u.username,name:u.name,role:u.role,title:u.title||u.role};
    setSession(sess); setRole(u.role);
    logActivity(null,"Login",u.role,sess.name);
    const defaultPages={Manager:"home",Sales:"pipeline",Finance:"home",Procurement:"home",QS:"home",Operations:"home",Design:"home",ProjectMover:"home",SalesOpsAdmin:"home",FinanceAssistant:"home"};
    setPage(defaultPages[u.role]||"home");
    localStorage.setItem(KEYS.session,JSON.stringify(sess));
    localStorage.setItem(KEYS.role,u.role);
    loadAllFromSupabase();
    return null;
  };
  // Verify a password against the CURRENT logged-in user's own stored hash
  // (used by the "change my password" flow) via the same server-side RPC as
  // login — u.passwordHash is no longer readable from the client, so this is
  // the only way to check the current password without knowing it in advance.
  const verifyCurrentPassword=async(username,password)=>{
    if(isSupabaseReady()){
      try{
        const{data,error}=await _rpcWithTimeout(supabase.rpc('verify_login',{p_username:username,p_password:password}));
        const row=Array.isArray(data)?data[0]:data;
        if(!error&&row?.found) return !!row.password_ok;
      }catch(e){ /* fall back to local check below */ }
    }
    const u=users.find(x=>x.username.toLowerCase()===username.toLowerCase());
    return u?checkPw(password,u.passwordHash,u.username):false;
  };
  const logout=async()=>{
    appLogout();
    setSession(null);
    setRole(null);
    setAuthView("login");
    setPage("home");
    sessionStorage.removeItem("gmd:lastPage");
    localStorage.removeItem(KEYS.session);
    localStorage.removeItem(KEYS.role);
  };
  const register=async(name,username,password,requestedRole)=>{
    if(!name||!username||!password) return "All fields are required.";
    if(users.find(u=>u.username.toLowerCase()===username.toLowerCase())) return "Username already taken.";
    if(password.length<6) return "Password must be at least 6 characters.";
    const uname=username.toLowerCase();
    const newUser={id:"u"+Date.now(),name,username:uname,passwordHash:await sha256Hash(password,uname),role:requestedRole,status:"pending",createdAt:today};
    upUsers(us=>[...us,newUser]);
    return null;
  };
  const approveUser =(id,role)=>upUsers(us=>us.map(u=>{if(u.id!==id)return u;const n={...u,status:"active",role};if(isSupabaseReady())sbUpsert('user_profiles',toSbUser(n),'id').catch(()=>{});return n;}));
  const rejectUser  =(id)    =>upUsers(us=>us.map(u=>{if(u.id!==id)return u;const n={...u,status:"rejected"};if(isSupabaseReady())sbUpsert('user_profiles',toSbUser(n),'id').catch(()=>{});return n;}));
  const deactivateUser=(id)  =>upUsers(us=>us.map(u=>{if(u.id!==id)return u;const n={...u,status:"inactive"};if(isSupabaseReady())sbUpsert('user_profiles',toSbUser(n),'id').catch(()=>{});return n;}));
  const deleteUser  =(id)    =>{upUsers(us=>us.filter(u=>u.id!==id));if(isSupabaseReady())sbDelete('user_profiles',id).catch(()=>{});};
  const resetPw     =async(id,pw)=>{const u=users.find(x=>x.id===id);if(!u)return;const n={...u,passwordHash:await sha256Hash(pw,u.username)};upUsers(us=>us.map(x=>x.id===id?n:x));if(isSupabaseReady())sbUpsert('user_profiles',toSbUser(n),'id').catch(()=>{});};
  const createUser  =async(name,username,password,role,title)=>{
    const uname=username.toLowerCase().trim();
    const newUser={id:uid(),name:name.trim(),username:uname,passwordHash:await sha256Hash(password,uname),role,title:title.trim()||role,status:"active",createdAt:today};
    upUsers(us=>[...us,newUser]);
    if(isSupabaseReady()) sbUpsert('user_profiles',toSbUser(newUser),'id').catch(()=>{});
  };
  // ── Derived ───────────────────────────────────────────────────────────────
  const wonDeals    =useMemo(()=>deals.filter(d=>WON_STAGES.includes(d.stage)),[deals]);
  const completedDeals=useMemo(()=>deals.filter(d=>d.stage==="14 · Completed"),[deals]);
  const closedDeals=useMemo(()=>deals.filter(d=>d.stage==="12 · Close-Out"),[deals]);
  // Auto-create project entries for any won deal that doesn't have one yet
  // Depends on both wonDeals.length AND projs key count so it re-runs after Supabase loads projs
  const projsKeyCount=Object.keys(projs).length;
  useEffect(()=>{
    // Standby PO umbrellas have no production of their own (their jobs do),
    // so don't spin up an empty ₱0 project shell for them.
    const missing=wonDeals.filter(d=>!projs[d.id]&&!d.standbyPO);
    if(missing.length>0){
      const patch={};
      missing.forEach(d=>{patch[d.id]=emptyProject();});
      upProjs(ps=>({...ps,...patch}));
    }
  // eslint-disable-next-line
  },[wonDeals.length,projsKeyCount]);

  // Auto-mark Finance DONE when project is fully paid
  useEffect(()=>{
    wonDeals.forEach(d=>{
      const ms=billings.filter(b=>b.dealId===d.id&&b.status!=="Cancelled");
      if(ms.length===0) return;
      const allPaid=ms.every(m=>m.status==="Fully Paid");
      const card=pcards[d.id];
      if(allPaid&&card&&!card.departments?.Finance?.done){
        markDeptDone(d.id,"Finance",true);
      }
    });
  // eslint-disable-next-line
  },[billings.length]);
  const projList  =useMemo(()=>wonDeals.filter(d=>projs[d.id]),[wonDeals,projs]);
  const isPauloGate = stage => PAULO_GATE.includes(stage);
  const clientName=useCallback(id=>deals.find(d=>d.id===id)?.client||`Project #${id}`,[deals]);
  // useCallback so this stays referentially stable across renders — otherwise
  // a plain inline function is a NEW reference every render, which defeats
  // React.memo on anything it's passed to (e.g. WIPView below) since one of
  // its props would always look "changed" even when nothing did.
  const overallProg=useCallback(p=>{const si=PROD_STAGES.indexOf(p.currentStage);return Math.round(si*25+(p.progress[p.currentStage]||0)*0.25);},[]);
  const costOf    =p=>(p.materials||[]).reduce((s,m)=>s+m.cost,0)+(p.laborCost||0)+(p.overhead||0);
  const marginOf  =(p,d)=>d&&costOf(p)<d.value?Math.round((d.value-costOf(p))/d.value*100):0;
  const totRev    =useMemo(()=>wonDeals.reduce((s,d)=>s+d.value,0),[wonDeals]);
  const totExp    =useMemo(()=>exps.reduce((s,e)=>s+e.amount,0),[exps]);
  const escalations = useMemo(()=>{
    const list = [];
    const todayD = today;
    const in7days = new Date(); in7days.setDate(in7days.getDate()+7);
    const in7str = in7days.toISOString().slice(0,10);
    // O(1) Map lookups instead of O(n) find() on every iteration
    const wonMap  = new Map(wonDeals.map(d=>[d.id,d]));
    const dealMap = new Map(deals.map(d=>[d.id,d]));
    const billedDealIds = new Set(billings.filter(b=>b.status!=='Cancelled').map(b=>b.dealId));
    // E-1: billing milestones overdue
    billings.forEach(b=>{
      if(b.dueDate && b.dueDate < todayD && b.status !== 'Fully Paid' && b.status !== 'Cancelled'){
        const deal = wonMap.get(b.dealId);
        if(deal) list.push({type:'E-1',dealId:b.dealId,client:deal.client,label:`Overdue: ${b.name||b.label||'Invoice'} (due ${b.dueDate})`,severity:'high'});
      }
    });
    // E-2: addenda in Discovered status
    addenda.forEach(a=>{
      if(a.status==='Discovered'){
        const deal = wonMap.get(a.dealId);
        if(deal) list.push({type:'E-2',dealId:a.dealId,client:deal.client,label:`Unresolved scope change: ${a.title||'Addendum'}`,severity:'medium'});
      }
    });
    // E-3: punchlist SLA breach
    wonDeals.forEach(d=>{
      if(d.stage==='11 · Punchlist'){
        const proj = projs[d.id];
        const startDate = proj?.stageDates?.Punchlist?.s;
        if(startDate && bizDaysElapsed(startDate) > BUSINESS_DAYS_SLA){
          list.push({type:'E-3',dealId:d.id,client:d.client,label:`Punchlist SLA breached (${bizDaysElapsed(startDate)} biz days)`,severity:'high'});
        }
      }
    });
    // E-4: DRF deadline within 7 days
    drfs.forEach(drf=>{
      if(drf.designDeadline && drf.status!=='Done' && drf.status!=='Cancelled' && drf.designDeadline>=todayD && drf.designDeadline<=in7str){
        const deal = wonMap.get(drf.dealId)||dealMap.get(drf.dealId);
        const daysLeft = Math.ceil((new Date(drf.designDeadline)-new Date(todayD))/(1000*60*60*24));
        list.push({type:'E-4',dealId:drf.dealId,client:deal?.client||drf.client||'?',label:`DRF ${drf.drfNo||''} deadline in ${daysLeft}d (${drf.designDeadline})`,severity:'medium'});
      }
    });
    // E-5: PO delivery overdue
    prs.forEach(pr=>{
      if(pr.deliveryDate && pr.deliveryDate < todayD && !['Delivered','Cancelled'].includes(pr.status)){
        const deal = wonMap.get(pr.dealId||pr.projectId);
        list.push({type:'E-5',dealId:pr.dealId||pr.projectId,client:deal?.client||'?',label:`PO overdue: ${pr.item||'Item'} (due ${pr.deliveryDate})`,severity:'high'});
      }
    });
    // E-6: Budget requests pending >3 days
    breqs.forEach(br=>{
      if(br.status==='Pending' && br.createdAt){
        const created = new Date(br.createdAt); const diff = Math.floor((new Date()-created)/(1000*60*60*24));
        if(diff>3){
          const deal = wonMap.get(br.dealId);
          list.push({type:'E-6',dealId:br.dealId,client:deal?.client||br.title||'?',label:`Budget request pending ${diff}d: ${br.title||'Request'}`,severity:'low'});
        }
      }
    });
    // E-7: Won projects with no billing milestones — only flag from Fabrication stage onwards
    // Kickoff & Briefing are too early to require milestones
    const BILLING_REQUIRED_STAGES=["08 · Fabrication","09 · Site & Billing","10 · Installation","11 · Punchlist","12 · Close-Out"];
    wonDeals.forEach(d=>{
      if(!billedDealIds.has(d.id)&&BILLING_REQUIRED_STAGES.includes(d.stage)) list.push({type:'E-7',dealId:d.id,client:d.client,label:`No billing milestone set for active project`,severity:'medium'});
    });
    return list;
  },[billings,addenda,wonDeals,projs,drfs,prs,breqs,deals,today]);
  // Billing milestones are the source of truth for "collected" once a deal has a schedule —
  // deal.amountPaid can drift (legacy imports, manual edits) with nothing to catch it, which is
  // exactly how Sales Pipeline and Billing ended up showing different numbers for the same deal.
  // Falls back to deal.amountPaid only for deals that never got a billing schedule.
  const dealCollected=(d)=>{
    const allMs=billings.filter(b=>b.dealId===d.id);
    if(!allMs.length) return Number(d.amountPaid||0); // no schedule → legacy fallback
    // Has a schedule: sum payments on non-cancelled milestones only, so collected
    // stays consistent with deal.invoiced (which also excludes Cancelled).
    // Bounced payments never landed, so they don't count as collected.
    return allMs.filter(b=>b.status!=='Cancelled').reduce((s,m)=>s+(m.payments||[]).filter(p=>!p.bounced).reduce((ps,p)=>ps+Number(p.amount||0),0),0);
  };
  const totColl   =useMemo(()=>wonDeals.reduce((s,d)=>s+dealCollected(d),0),[wonDeals,billings]);
  const totOut    =useMemo(()=>Math.max(0,wonDeals.reduce((s,d)=>s+Number(d.invoiced||0)-dealCollected(d),0)),[wonDeals,billings]);

  // Auto-mark overdue billing milestones — runs once when billings load, then daily
  useEffect(()=>{
    if(!billings.length) return;
    const toMark=billings.filter(b=>b.dueDate&&b.dueDate<today&&!['Fully Paid','Cancelled','Overdue'].includes(b.status));
    if(!toMark.length) return;
    upBillings(bs=>bs.map(b=>toMark.find(m=>m.id===b.id)?{...b,status:'Overdue'}:b));
    if(isSupabaseReady()){
      toMark.forEach(b=>sbUpdate('billing_milestones',b.id,{status:'Overdue',updated_at:new Date().toISOString()}).catch(()=>{}));
    }
  },[billings.length,today]); // eslint-disable-line

  // Daily bot alerts: overdue payables + low inventory
  useEffect(()=>{
    if(!isSupabaseReady()||!botSettings?.token) return;
    const overdueP=payables.filter(p=>p.status==="Unpaid"&&p.dueDate&&p.dueDate<today);
    if(overdueP.length>0){
      const total=overdueP.reduce((s,p)=>s+Number(p.amount||0),0);
      const lines=overdueP.slice(0,5).map(p=>`• ${p.payee||p.description||"?"} — ₱${Number(p.amount||0).toLocaleString("en-PH",{maximumFractionDigits:0})} (due ${p.dueDate})`).join("\n");
      const msg=`⚠️ <b>Overdue Payables Alert</b>\n${overdueP.length} payable${overdueP.length!==1?"s":""} overdue — ₱${total.toLocaleString("en-PH",{maximumFractionDigits:0})} total\n\n${lines}${overdueP.length>5?`\n…and ${overdueP.length-5} more`:""}`;
      sendTelegramNotification("financialcontrol",msg);
      sendTelegramNotification("management",msg);
    }
    const lowStock=inventory.filter(i=>i.status!=="Inactive"&&i.reorderPoint>0&&i.qtyOnHand<=i.reorderPoint);
    if(lowStock.length>0){
      const lines=lowStock.slice(0,5).map(i=>`• ${i.name} — ${i.qtyOnHand} ${i.unit} (reorder at ${i.reorderPoint})`).join("\n");
      const msg=`📦 <b>Low Inventory Alert</b>\n${lowStock.length} item${lowStock.length!==1?"s":""} at or below reorder point\n\n${lines}${lowStock.length>5?`\n…and ${lowStock.length-5} more`:""}`;
      sendTelegramNotification("warehouse",msg);
      sendTelegramNotification("procurement",msg);
    }
  },[today]); // eslint-disable-line

  // ── Dashboard KPI memos — pre-computed so render is instant ──────────────
  const pipeDeals      =useMemo(()=>deals.filter(d=>isActivePipeline(d.stage)),[deals]);
  const pipeVal        =useMemo(()=>pipeDeals.reduce((s,d)=>s+Number(d.value||0),0),[pipeDeals]);
  const awardReqCnt    =useMemo(()=>deals.filter(d=>d.notes&&d.notes.includes("[AWARD REQUEST")).length,[deals]);
  const overdueInvCnt  =useMemo(()=>billings.filter(b=>b.dueDate&&b.dueDate<today&&b.status!=="Fully Paid"&&b.status!=="Cancelled").length,[billings]);
  const overdueTATCnt  =useMemo(()=>wonDeals.filter(d=>d.stage!=="12 · Close-Out"&&d.stage!=="14 · Completed"&&pcards[d.id]?.targetEndDate&&pcards[d.id].targetEndDate<today&&!DEPT_ORDER.every(dept=>pcards[d.id]?.departments?.[dept]?.done)).length,[wonDeals,pcards]);
  const qsPendingCnt   =useMemo(()=>jos.filter(j=>j.budgetStatus==="QS Budget Pending"&&!Object.values(budgets[j.dealId]||{}).some(v=>Number(v)>0)).length,[jos,budgets]);
  const mrPendingCnt   =useMemo(()=>mreqs.filter(m=>m.status==="Submitted").length,[mreqs]);
  const addendaAlertCnt=useMemo(()=>addenda.filter(a=>!a.salesNotified&&a.status!=="Rejected").length,[addenda]);
  const activeJOCnt    =useMemo(()=>jos.filter(j=>j.status==="Active").length,[jos]);
  const pendingPRCnt   =useMemo(()=>prs.filter(p=>p.status==="Pending Approval").length,[prs]);
  const billOutstanding=useMemo(()=>Math.max(0,billings.reduce((s,m)=>s+Number(m.amount||0)-(m.payments||[]).reduce((ps,p)=>ps+Number(p.amount||0),0),0)),[billings]);
  const overdueInvMs   =useMemo(()=>billings.filter(m=>m.dueDate&&m.dueDate<today&&m.status!=="Fully Paid"&&m.status!=="Cancelled").length,[billings]);
  const breqPendingCnt =useMemo(()=>breqs.filter(b=>b.status==="Pending").length,[breqs]);
  const openPOCnt      =useMemo(()=>prs.filter(p=>["Pending Approval","Approved","PO Issued"].includes(p.status)).length,[prs]);
  const toBuyCnt       =useMemo(()=>swatches.filter(s=>s.status==="To Buy").length,[swatches]);
  const overdueProjectCnt=useMemo(()=>wonDeals.filter(d=>pcards[d.id]?.targetEndDate&&pcards[d.id].targetEndDate<today&&!DEPT_ORDER.every(dept=>pcards[d.id]?.departments?.[dept]?.done)).length,[wonDeals,pcards]);

  // ── Modals ────────────────────────────────────────────────────────────────
  const[dealModal,  setDealModal] =useState(false);
