// Finance Daily Digest — self-contained snapshot (Collections/AR · Cash Position
// · Billing/Payables · Profitability) with a Send-to-Telegram action. Computes
// everything from the raw app data so it can be dropped on any finance screen.
// Mirrors the panel originally embedded in Finance → Overview.
function FinanceDigestPanel({billings=[],exps=[],wonDeals=[],completedDeals=[],deals=[],payables=[],cashPositions={},today,isMobile,sendTelegramNotification,toastEmit}){
  const now=new Date();
  const cy=now.getFullYear();
  const totalBilled=billings.filter(b=>b.status!=="Cancelled").reduce((s,b)=>s+Number(b.amount||0),0);
  const totalCollected=billings.reduce((s,b)=>(b.payments||[]).reduce((ss,p)=>ss+Number(p.amount||0),s),0);
  const totalExpenses=exps.reduce((s,e)=>s+Number(e.amount||0),0);
  const grossProfit=totalCollected-totalExpenses;
  const grossMargin=totalCollected>0?Math.round(grossProfit/totalCollected*100):0;
  const collectionRate=totalBilled>0?Math.round(totalCollected/totalBilled*100):0;
  const outstanding=Math.max(0,totalBilled-totalCollected);
  const dso=totalCollected>0?Math.round(outstanding/(totalCollected/365)):0;
  const backlog=wonDeals.reduce((s,d)=>{const billed=billings.filter(b=>b.dealId===d.id&&b.status!=="Cancelled").reduce((bs,b)=>bs+Number(b.amount||0),0);return s+Math.max(0,Number(d.value||0)-billed);},0);
  const y12ago=new Date();y12ago.setFullYear(y12ago.getFullYear()-1);
  const recentDeals=deals.filter(d=>{const dt=new Date(d.createdAt||"2020-01-01");return dt>=y12ago;});
  const winRate=recentDeals.length>0?Math.round(recentDeals.filter(d=>WON_STAGES.includes(d.stage)||d.stage==="14 · Completed").length/recentDeals.length*100):0;
  const avgDeal=wonDeals.length>0?Math.round(wonDeals.reduce((s,d)=>s+Number(d.value||0),0)/wonDeals.length):0;
  const months6=Array.from({length:6},(_,i)=>{const d=new Date(now.getFullYear(),now.getMonth()-5+i,1);return{y:d.getFullYear(),m:d.getMonth()};});
  const monthlyRev=months6.map(({y,m})=>billings.filter(b=>b.status!=="Cancelled").reduce((s,b)=>{const ds=b.invoiceDate||b.dueDate;if(!ds)return s;const d=new Date(ds);return(!isNaN(d)&&d.getFullYear()===y&&d.getMonth()===m)?s+Number(b.amount||0):s;},0));
  const clientMap={};billings.forEach(b=>{const d=wonDeals.find(x=>x.id===b.dealId)||completedDeals.find(x=>x.id===b.dealId);if(!d)return;const k=d.client;if(!clientMap[k])clientMap[k]=0;clientMap[k]+=(b.payments||[]).reduce((s,p)=>s+Number(p.amount||0),0);});
  const topClients=Object.entries(clientMap).sort(([,a],[,b])=>b-a).slice(0,5);
  const totalPayables=payables.filter(p=>p.status==="Unpaid").reduce((s,p)=>s+Number(p.amount||0),0);
  const overduePayables=payables.filter(p=>p.status==="Unpaid"&&p.dueDate&&p.dueDate<today).length;
  const overdueBillings=billings.filter(m=>m.dueDate&&m.dueDate<today&&m.status!=="Fully Paid"&&m.status!=="Cancelled");
  const unbilledProjects=wonDeals.filter(d=>billings.filter(b=>b.dealId===d.id&&b.status!=="Cancelled").length===0);
  const fmtM=v=>"₱"+Number(v).toLocaleString("en-PH",{maximumFractionDigits:0});
  const todayPos=cashPositions[today]||null;
  const BANK_LABELS={bpi:"BPI",metro:"Metrobank",china:"Chinabank",bdo:"BDO",security:"Security Bank",union:"UnionBank"};
  const cpBanks=todayPos?Object.entries(todayPos.banks||{}).map(([id,r])=>({id,label:BANK_LABELS[id]||id,beg:Number(r.beg||0),book:Number(r.book||0),end:Number(r.end||0)})).filter(b=>b.beg>0||b.book>0||b.end>0):[];
  const cpTotalBeg=cpBanks.reduce((s,b)=>s+b.beg,0);
  const cpTotalEnd=cpBanks.reduce((s,b)=>s+(b.end||b.book||b.beg),0);
  const cpCollections=(todayPos?.collections?.manualCollections||[]).reduce((s,c)=>s+Number(c.amount||0),0);
  const cpNetMove=cpTotalEnd-cpTotalBeg;
  const arOverdueAmt=overdueBillings.reduce((s,m)=>{const p=(m.payments||[]).reduce((ps,x)=>ps+Number(x.amount||0),0);return s+Math.max(0,Number(m.amount||0)-p);},0);
  const arAge30 =overdueBillings.filter(m=>{const d=Math.floor((now-new Date(m.dueDate))/(864e5));return d<=30;}).length;
  const arAge60 =overdueBillings.filter(m=>{const d=Math.floor((now-new Date(m.dueDate))/(864e5));return d>30&&d<=60;}).length;
  const arAge90p=overdueBillings.filter(m=>{const d=Math.floor((now-new Date(m.dueDate))/(864e5));return d>60;}).length;
  const arStatus=overdueBillings.length===0?"ok":arAge90p>0?"danger":"warning";
  const cpStatus=!todayPos?"warning":cpTotalEnd<500000?"danger":cpNetMove<0?"warning":"ok";
  const overduePayablesAmt=payables.filter(p=>p.status==="Unpaid"&&p.dueDate&&p.dueDate<today).reduce((s,p)=>s+Number(p.amount||0),0);
  const billStatus=overduePayables>0?"danger":unbilledProjects.length>0?"warning":"ok";
  const profStatus=grossMargin<20?"danger":grossMargin<30?"warning":"ok";
  const prevMonthRev=monthlyRev[monthlyRev.length-2]||0;
  const thisMonthRev=monthlyRev[monthlyRev.length-1]||0;
  const revTrend=prevMonthRev>0?Math.round((thisMonthRev-prevMonthRev)/prevMonthRev*100):0;
  const digestAlerts=[];
  if(overdueBillings.length>0) digestAlerts.push({icon:"🚨",text:`${overdueBillings.length} overdue invoice${overdueBillings.length!==1?"s":""} — ${fmtM(arOverdueAmt)} uncollected`});
  if(grossMargin<25) digestAlerts.push({icon:"📉",text:`Gross margin at ${grossMargin}% — below 25% target`});
  if(dso>90) digestAlerts.push({icon:"⏳",text:`DSO is ${dso} days — clients are paying very slowly`});
  if(unbilledProjects.length>0) digestAlerts.push({icon:"📋",text:`${unbilledProjects.length} awarded project${unbilledProjects.length!==1?"s":""} with no milestones billed yet`});
  if(overduePayables>0) digestAlerts.push({icon:"📤",text:`${overduePayables} overdue payable${overduePayables!==1?"s":""} — ${fmtM(overduePayablesAmt)}`});
  if(!todayPos) digestAlerts.push({icon:"⚠️",text:"No cash position entry for today — please update Daily Cash Position"});
  if(digestAlerts.length===0) digestAlerts.push({icon:"✅",text:"All financial indicators are on track — no alerts today."});
  const statusColor={ok:"#059669",warning:"#d97706",danger:"#dc2626"};
  const statusBg={ok:"#f0fdf4",warning:"#fffbeb",danger:"#fef2f2"};
  const statusBorder={ok:"#bbf7d0",warning:"#fde68a",danger:"#fecaca"};
  const statusLabel={ok:"✅ Good",warning:"⚠️ Watch",danger:"🔴 Action Needed"};
  const sendDigest=async()=>{
    const dateStr=now.toLocaleDateString("en-PH",{weekday:"long",year:"numeric",month:"long",day:"numeric"});
    const lines=[
      `💼 <b>GMD Finance Daily Digest</b>`,`📅 ${dateStr}`,``,
      `🧾 <b>COLLECTIONS / AR</b>  ${arStatus==="ok"?"✅":arStatus==="danger"?"🔴":"⚠️"}`,
      `• Total Billed: ${fmtM(totalBilled)}`,
      `• Collected: ${fmtM(totalCollected)} (${collectionRate}% rate)`,
      `• Outstanding AR: ${fmtM(outstanding)}`,
      `• DSO: ${dso} days`,
      ...(overdueBillings.length>0?[`• Overdue Invoices: ${overdueBillings.length} — ${fmtM(arOverdueAmt)}`]:[`• No overdue invoices ✅`]),
      ``,
      `💵 <b>DAILY CASH POSITION</b>  ${cpStatus==="ok"?"✅":cpStatus==="danger"?"🔴":"⚠️"}`,
      ...(todayPos?[`• Opening: ${fmtM(cpTotalBeg)}`,`• Closing: ${fmtM(cpTotalEnd)}`,`• Collections Today: ${fmtM(cpCollections)}`,`• Net Movement: ${cpNetMove>=0?"▲":"▼"} ${fmtM(Math.abs(cpNetMove))}`]:[`• ⚠️ No cash position logged for today`]),
      ``,
      `📤 <b>BILLING / PAYABLES</b>  ${billStatus==="ok"?"✅":billStatus==="danger"?"🔴":"⚠️"}`,
      `• Unpaid Payables: ${fmtM(totalPayables)}`,
      ...(overduePayables>0?[`• Overdue Payables: ${overduePayables} items — ${fmtM(overduePayablesAmt)}`]:[`• No overdue payables ✅`]),
      ...(unbilledProjects.length>0?[`• Unbilled Projects: ${unbilledProjects.length}`]:[]),
      `• Contract Backlog: ${fmtM(backlog)}`,
      ``,
      `📈 <b>PROFITABILITY</b>  ${profStatus==="ok"?"✅":profStatus==="danger"?"🔴":"⚠️"}`,
      `• Gross Margin: ${grossMargin}%`,
      `• Gross Profit: ${fmtM(grossProfit)}`,
      `• Total Expenses: ${fmtM(totalExpenses)}`,
      `• This Month Revenue: ${fmtM(thisMonthRev)}${revTrend!==0?` (${revTrend>0?"+":""}${revTrend}% vs last month)`:""}`,
      `• Win Rate: ${winRate}% | Avg Deal: ${fmtM(avgDeal)}`,
      ``,
      `🚦 <b>ALERTS</b>`,...digestAlerts.map(a=>`${a.icon} ${a.text}`),
      ``,`<i>Sent from FabHub Finance · ${dateStr}</i>`,
    ];
    try{ await sendTelegramNotification&&sendTelegramNotification("financialcontrol",lines.join("\n")); toastEmit&&toastEmit("Daily digest sent to Financial Control ✅","success"); }
    catch(e){ toastEmit&&toastEmit("Could not send digest — check Telegram settings.","error"); }
  };
  const ReviewSection=({icon,title,status,children})=>(
    <div style={{background:statusBg[status],border:`1.5px solid ${statusBorder[status]}`,borderRadius:10,padding:"12px 14px"}}>
      <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:8}}>
        <span style={{fontWeight:700,color:"#0f172a",fontSize:".82rem"}}>{icon} {title}</span>
        <span style={{fontSize:".68rem",fontWeight:700,color:statusColor[status],background:"#fff",border:`1px solid ${statusBorder[status]}`,borderRadius:20,padding:"2px 8px"}}>{statusLabel[status]}</span>
      </div>
      <div style={{display:"flex",flexDirection:"column",gap:3}}>{children}</div>
    </div>
  );
  const Row=({label,value,color})=>(
    <div style={{display:"flex",justifyContent:"space-between",alignItems:"center"}}>
      <span style={{fontSize:".75rem",color:"#64748b"}}>{label}</span>
      <span style={{fontSize:".78rem",fontWeight:600,color:color||"#0f172a"}}>{value}</span>
    </div>
  );
  return(
    <div style={{background:"#fff",border:"1.5px solid #e2e8f0",borderRadius:12,padding:"14px 16px",marginBottom:16}}>
      <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:12,flexWrap:"wrap",gap:8}}>
        <div style={{display:"flex",alignItems:"center",gap:8}}>
          <span style={{fontSize:"1rem"}}>📡</span>
          <span style={{fontWeight:700,color:"#0f172a",fontSize:".85rem"}}>Finance Daily Digest</span>
          <span style={{fontSize:".68rem",color:"#94a3b8"}}>— {now.toLocaleDateString("en-PH",{weekday:"short",month:"short",day:"numeric"})}</span>
        </div>
        <button onClick={sendDigest} style={{background:"#0f172a",border:"none",borderRadius:8,padding:"7px 16px",fontFamily:"inherit",fontSize:".75rem",fontWeight:700,color:"#fff",cursor:"pointer",display:"flex",alignItems:"center",gap:6}}>
          <span>📲</span> Send to Telegram
        </button>
      </div>
      <div style={{display:"grid",gridTemplateColumns:isMobile?"1fr":"1fr 1fr",gap:10}}>
        <ReviewSection icon="🧾" title="Collections / AR" status={arStatus}>
          <Row label="Outstanding AR" value={fmtM(outstanding)} color={outstanding>0?"#ef4444":"#059669"}/>
          <Row label="Collection Rate" value={collectionRate+"%"} color={collectionRate>=50?"#059669":"#d97706"}/>
          <Row label="DSO" value={dso+" days"} color={dso>90?"#dc2626":dso>60?"#d97706":"#059669"}/>
          {overdueBillings.length>0&&<Row label="Overdue Invoices" value={`${overdueBillings.length} — ${fmtM(arOverdueAmt)}`} color="#dc2626"/>}
          {overdueBillings.length===0&&<Row label="Overdue" value="None ✅" color="#059669"/>}
        </ReviewSection>
        <ReviewSection icon="💵" title="Daily Cash Position" status={cpStatus}>
          {todayPos?<>
            <Row label="Opening Balance" value={fmtM(cpTotalBeg)}/>
            <Row label="Closing Balance" value={fmtM(cpTotalEnd)} color={cpTotalEnd<500000?"#dc2626":"#059669"}/>
            <Row label="Collections Today" value={fmtM(cpCollections)} color="#059669"/>
            <Row label="Net Movement" value={(cpNetMove>=0?"+":"")+fmtM(cpNetMove)} color={cpNetMove>=0?"#059669":"#dc2626"}/>
          </> : <Row label="Status" value="⚠️ Not logged today" color="#d97706"/>}
        </ReviewSection>
        <ReviewSection icon="📤" title="Billing / Payables" status={billStatus}>
          <Row label="Unpaid Payables" value={fmtM(totalPayables)} color={totalPayables>0?"#ef4444":"#059669"}/>
          <Row label="Overdue Payables" value={overduePayables>0?`${overduePayables} — ${fmtM(overduePayablesAmt)}`:"None ✅"} color={overduePayables>0?"#dc2626":"#059669"}/>
          <Row label="Unbilled Projects" value={unbilledProjects.length>0?`${unbilledProjects.length} projects`:"None ✅"} color={unbilledProjects.length>0?"#d97706":"#059669"}/>
          <Row label="Contract Backlog" value={fmtM(backlog)} color="#8b5cf6"/>
        </ReviewSection>
        <ReviewSection icon="📈" title="Profitability" status={profStatus}>
          <Row label="Gross Margin" value={grossMargin+"%"} color={grossMargin>=30?"#059669":grossMargin>=20?"#d97706":"#dc2626"}/>
          <Row label="Gross Profit" value={fmtM(grossProfit)} color={grossProfit>=0?"#059669":"#dc2626"}/>
          <Row label="Total Expenses" value={fmtM(totalExpenses)} color="#ef4444"/>
          <Row label="This Month Rev." value={fmtM(thisMonthRev)} color="#3b82f6"/>
          {revTrend!==0&&<Row label="vs Last Month" value={(revTrend>0?"+":"")+revTrend+"%"} color={revTrend>0?"#059669":"#dc2626"}/>}
          <Row label="Win Rate" value={winRate+"%"} color={winRate>=40?"#059669":"#d97706"}/>
        </ReviewSection>
      </div>
    </div>
  );
}

// Aerwin-styled Finance module header + tab bar. Gives the finance/accounting
// screens the look of the finance team's standalone ERP (navy banner, gold
// wordmark, a Purchase-to-Payment tab strip with count badges) while staying
// inside FabHub. `active` is one of dashboard|po|ap|payments|cv; `go(key)` does
// the navigation; `counts` supplies the badge numbers.
// ── Aerwin ERP design tokens + shared finance primitives ────────────────────
// Exact palette lifted from the finance team's standalone Purchase-to-Payment
// ERP so FabHub's finance screens read as the same product.
const ERP={navy:"#0B2545",navy2:"#132F5C",navyLight:"#EEF2F8",gold:"#C9A24B",goldDark:"#A8822F",ink:"#1B2430",muted:"#5B6472",line:"#DCE2EC",paper:"#FFFFFF",bg:"#F5F7FA",danger:"#B3413A",ok:"#2E7D4F",warn:"#B8862C",purple:"#6A3FA0"};
const ERP_TONE={default:ERP.gold,warn:ERP.warn,danger:ERP.danger,ok:ERP.ok,purple:ERP.purple};

// .stat — value card with a colored left accent bar (tone: default|warn|danger|ok|purple)
function ErpStat({label,value,foot,tone="default"}){
  return(
    <div style={{background:ERP.paper,border:`1px solid ${ERP.line}`,borderRadius:12,padding:"16px 18px",position:"relative",overflow:"hidden"}}>
      <div style={{position:"absolute",left:0,top:0,bottom:0,width:4,background:ERP_TONE[tone]||ERP.gold}}/>
      <div style={{fontSize:11.5,color:ERP.muted,textTransform:"uppercase",letterSpacing:".6px",fontWeight:600}}>{label}</div>
      <div style={{fontSize:24,fontWeight:700,color:ERP.navy,marginTop:4}}>{value}</div>
      {foot!=null&&<div style={{fontSize:11.5,color:ERP.muted,marginTop:4}}>{foot}</div>}
    </div>
  );
}
// .card — titled white panel
function ErpCard({title,desc,right,children,style}){
  return(
    <div style={{background:ERP.paper,border:`1px solid ${ERP.line}`,borderRadius:12,padding:"18px 20px",marginBottom:16,...style}}>
      {(title||right)&&(
        <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",gap:10,marginBottom:desc?4:14}}>
          {title&&<h2 style={{margin:0,fontSize:16,color:ERP.navy,fontWeight:700}}>{title}</h2>}
          {right}
        </div>
      )}
      {desc&&<p style={{margin:"0 0 14px",color:ERP.muted,fontSize:12.5}}>{desc}</p>}
      {children}
    </div>
  );
}
// Status badge, keyed to Aerwin's badge palette
const ERP_BADGE={open:{bg:"#E7EEFB",c:ERP.navy},invoiced:{bg:"#FDF1DC",c:ERP.warn},closed:{bg:"#E5F3EA",c:ERP.ok},unpaid:{bg:"#FBEAE8",c:ERP.danger},partial:{bg:"#FDF1DC",c:ERP.warn},paid:{bg:"#E5F3EA",c:ERP.ok},check:{bg:"#EEF2F8",c:ERP.navy},online:{bg:"#F0EAFB",c:ERP.purple},draft:{bg:"#EEF1F5",c:ERP.muted},approved:{bg:"#E7EEFB",c:ERP.navy},inactive:{bg:"#EEF1F5",c:ERP.muted}};
function ErpBadge({kind="open",children}){
  const s=ERP_BADGE[String(kind).toLowerCase()]||ERP_BADGE.open;
  return <span style={{display:"inline-block",padding:"3px 9px",borderRadius:20,fontSize:11,fontWeight:700,letterSpacing:".3px",background:s.bg,color:s.c}}>{children}</span>;
}
// Map a free-text status to a badge kind
function erpStatusKind(status){
  const s=String(status||"").toLowerCase();
  if(s.includes("paid")&&!s.includes("unpaid"))return"paid";
  if(s.includes("partial"))return"partial";
  if(s.includes("unpaid")||s.includes("overdue"))return"unpaid";
  if(s.includes("released")||s.includes("cleared"))return"closed";
  if(s.includes("for release")||s.includes("for payment")||s.includes("invoiced"))return"invoiced";
  if(s.includes("draft")||s.includes("logged"))return"draft";
  if(s.includes("cancel"))return"unpaid";
  if(s.includes("issued")||s.includes("open")||s.includes("approved"))return"open";
  return"open";
}
// Shared table styles (navy-light uppercase headers, hairline rows)
const erpTh={textAlign:"left",background:ERP.navyLight,color:ERP.navy,fontSize:11,textTransform:"uppercase",letterSpacing:".5px",padding:"9px 10px",borderBottom:`2px solid ${ERP.line}`,whiteSpace:"nowrap",fontWeight:700};
const erpTd={padding:"9px 10px",borderBottom:`1px solid ${ERP.line}`,verticalAlign:"top",fontSize:13,color:ERP.ink};
const erpThNum={...erpTh,textAlign:"right"};
const erpTdNum={...erpTd,textAlign:"right",fontVariantNumeric:"tabular-nums"};

function FinanceErpBar({active,go,counts={}}){
  const mob=window.innerWidth<768;
  const tabs=[
    {k:"dashboard",l:"Dashboard"},
    {k:"po",l:"Purchase Orders",n:counts.po},
    {k:"ap",l:"Accounts Payable",n:counts.ap},
    {k:"payments",l:"Payments",n:counts.payments},
    {k:"cv",l:"Check Vouchers",n:counts.cv},
  ];
  return(
    <div style={{marginBottom:mob?12:18}}>
      {/* The full GMD banner is desktop-only — on mobile it eats a whole screen
          of vertical space, so we drop it and let the tab strip lead. */}
      {!mob&&(
        <div style={{background:"linear-gradient(135deg,#0B2545 0%,#132F5C 100%)",borderRadius:12,padding:"18px 24px",display:"flex",justifyContent:"space-between",alignItems:"center",flexWrap:"wrap",gap:10,boxShadow:"0 4px 14px rgba(11,37,69,0.18)"}}>
          <div>
            <div style={{fontSize:18,fontWeight:700,color:"#fff",letterSpacing:".3px"}}>GMD <span style={{color:"#C9A24B"}}>Production Inc.</span></div>
            <div style={{fontSize:12,color:"#C7D4E8",marginTop:2,fontWeight:500}}>Purchase-to-Payment · Accounts Payable · Check Voucher · Chart of Accounts</div>
          </div>
          <span style={{background:"rgba(201,162,75,0.18)",border:"1px solid #C9A24B",color:"#C9A24B",borderRadius:20,padding:"5px 10px",fontSize:11,fontWeight:600,letterSpacing:"1.2px",textTransform:"uppercase"}}>Finance Module</span>
        </div>
      )}
      {/* Mobile: a horizontal-scroll tab strip (no wrapping, no huge min-widths).
          Desktop: keep the even flex row. */}
      <div style={{background:"#fff",border:"1px solid #DCE2EC",borderRadius:10,padding:mob?4:6,marginTop:mob?0:18,display:"flex",gap:6,flexWrap:mob?"nowrap":"wrap",overflowX:mob?"auto":"visible",WebkitOverflowScrolling:"touch"}}>
        {tabs.map(t=>{
          const on=t.k===active;
          return(
            <button key={t.k} onClick={()=>!on&&go&&go(t.k)} style={{display:"flex",alignItems:"center",justifyContent:"center",gap:6,flex:mob?"0 0 auto":1,minWidth:mob?"auto":108,whiteSpace:"nowrap",background:on?"#0B2545":"transparent",color:on?"#fff":"#5B6472",border:"none",borderRadius:8,padding:mob?"9px 14px":"10px 10px",fontFamily:"inherit",fontSize:13,fontWeight:600,cursor:on?"default":"pointer",transition:"all .15s ease"}}>
              {t.l}
              {t.n>0&&<span style={{background:on?"rgba(255,255,255,0.85)":"#C9A24B",color:"#0B2545",borderRadius:10,padding:"1px 7px",fontSize:11,fontWeight:700}}>{t.n}</span>}
            </button>
          );
        })}
      </div>
    </div>
  );
}

function ChartOfAccountsView({chartOfAccounts=[],saveChartOfAccounts,session,role}){
  const canEdit=["Manager","Finance","Accounting"].includes(role);
  const[form,setForm]=React.useState({code:"",name:"",type:"Expense"});
  const[editId,setEditId]=React.useState(null);
  const[q,setQ]=React.useState("");
  const sorted=[...chartOfAccounts].sort((a,b)=>String(a.code).localeCompare(String(b.code)));
  const ql=q.trim().toLowerCase();
  const filtered=ql?sorted.filter(a=>String(a.code).includes(ql)||(a.name||"").toLowerCase().includes(ql)):sorted;
  const seedDefaults=async ()=>{
    if(chartOfAccounts.length){if(!(await uiConfirm("Append the default chart to your existing accounts? Duplicates (same code) are skipped.")))return;}
    const have=new Set(chartOfAccounts.map(a=>String(a.code)));
    const add=DEFAULT_COA.filter(d=>!have.has(d.code)).map(d=>({id:uid(),code:d.code,name:d.name,type:d.type,active:true}));
    if(!add.length){uiAlert("All default accounts are already in your chart.");return;}
    saveChartOfAccounts([...chartOfAccounts,...add]);
  };
  const submit=()=>{
    const code=form.code.trim(),name=form.name.trim();
    if(!code||!name){uiAlert("Account code and name are required.");return;}
    if(chartOfAccounts.some(a=>String(a.code)===code&&a.id!==editId)){uiAlert(`Account code ${code} already exists.`);return;}
    if(editId) saveChartOfAccounts(chartOfAccounts.map(a=>a.id===editId?{...a,code,name,type:form.type}:a));
    else saveChartOfAccounts([...chartOfAccounts,{id:uid(),code,name,type:form.type,active:true}]);
    setForm({code:"",name:"",type:"Expense"});setEditId(null);
  };
  const startEdit=(a)=>{setEditId(a.id);setForm({code:String(a.code),name:a.name,type:a.type});};
  const del=async (a)=>{if((await uiConfirm(`Delete account ${a.code} — ${a.name}?`))) saveChartOfAccounts(chartOfAccounts.filter(x=>x.id!==a.id));};
  const inpSt={border:"1.5px solid #e2e8f0",borderRadius:7,padding:"7px 10px",fontFamily:"inherit",fontSize:".82rem",outline:"none",boxSizing:"border-box"};
  return(
    <div style={{maxWidth:860,margin:"0 auto"}}>
      <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-end",gap:12,marginBottom:6,flexWrap:"wrap"}}>
        <div>
          <h2 style={{margin:"0 0 4px",fontWeight:900,fontSize:"1.4rem",color:"#0f172a",fontFamily:"'Barlow Condensed',sans-serif"}}>📒 Chart of Accounts</h2>
          <p style={{margin:0,fontSize:".8rem",color:"#64748b"}}>The accounts used to classify every transaction. {chartOfAccounts.length} account{chartOfAccounts.length!==1?"s":""}.</p>
        </div>
        {canEdit&&<button onClick={seedDefaults} style={{background:"#f1f5f9",border:"1.5px solid #e2e8f0",borderRadius:9,padding:"9px 16px",color:"#475569",fontFamily:"inherit",fontWeight:700,fontSize:".82rem",cursor:"pointer",whiteSpace:"nowrap"}}>Load standard chart of accounts</button>}
      </div>
      {canEdit&&(
        <div style={{background:"#f8fafc",border:"1.5px solid #e2e8f0",borderRadius:10,padding:"12px 14px",margin:"14px 0",display:"flex",gap:8,alignItems:"flex-end",flexWrap:"wrap"}}>
          <div><div style={{fontSize:".65rem",fontWeight:700,color:"#64748b",marginBottom:3}}>Code</div><input value={form.code} onChange={e=>setForm(f=>({...f,code:e.target.value}))} placeholder="e.g. 6020" style={{...inpSt,width:90}}/></div>
          <div style={{flex:1,minWidth:160}}><div style={{fontSize:".65rem",fontWeight:700,color:"#64748b",marginBottom:3}}>Account Name</div><input value={form.name} onChange={e=>setForm(f=>({...f,name:e.target.value}))} placeholder="e.g. Rent" onKeyDown={e=>e.key==="Enter"&&submit()} style={{...inpSt,width:"100%"}}/></div>
          <div><div style={{fontSize:".65rem",fontWeight:700,color:"#64748b",marginBottom:3}}>Type</div><select value={form.type} onChange={e=>setForm(f=>({...f,type:e.target.value}))} style={{...inpSt}}>{COA_TYPES.map(t=><option key={t}>{t}</option>)}</select></div>
          <button onClick={submit} style={{background:"#1e293b",border:"none",borderRadius:8,padding:"8px 16px",color:"#fff",fontFamily:"inherit",fontWeight:700,fontSize:".8rem",cursor:"pointer"}}>{editId?"Save":"＋ Add"}</button>
          {editId&&<button onClick={()=>{setEditId(null);setForm({code:"",name:"",type:"Expense"});}} style={{background:"none",border:"1.5px solid #e2e8f0",borderRadius:8,padding:"8px 14px",color:"#64748b",fontFamily:"inherit",fontWeight:600,fontSize:".8rem",cursor:"pointer"}}>Cancel</button>}
        </div>
      )}
      {chartOfAccounts.length===0?(
        <div style={{background:"#fff",borderRadius:14,border:"1.5px dashed #cbd5e1",padding:"44px 24px",textAlign:"center"}}>
          <div style={{fontSize:"1.8rem",marginBottom:8}}>📒</div>
          <div style={{fontWeight:700,color:"#0f172a",fontSize:".95rem",marginBottom:4}}>No accounts yet</div>
          <div style={{fontSize:".8rem",color:"#64748b",marginBottom:16}}>Load the GMD default chart to get started, then customize it.</div>
          {canEdit&&<button onClick={seedDefaults} style={{background:"#1e293b",border:"none",borderRadius:9,padding:"9px 18px",color:"#fff",fontFamily:"inherit",fontWeight:700,fontSize:".82rem",cursor:"pointer"}}>Load GMD default chart</button>}
        </div>
      ):(
        <>
          <input value={q} onChange={e=>setQ(e.target.value)} placeholder="Search by code or name…" style={{...inpSt,width:"100%",padding:"9px 13px",marginBottom:14}}/>
          {COA_TYPES.map(type=>{
            const rows=filtered.filter(a=>a.type===type);
            if(!rows.length) return null;
            return(
              <div key={type} style={{marginBottom:18}}>
                <div style={{display:"flex",alignItems:"center",gap:8,marginBottom:6}}>
                  <span style={{width:10,height:10,borderRadius:3,background:COA_TYPE_CLR[type]}}/>
                  <span style={{fontWeight:800,fontSize:".8rem",textTransform:"uppercase",letterSpacing:".5px",color:"#0f172a"}}>{type}</span>
                  <span style={{fontSize:".7rem",color:"#94a3b8"}}>{rows.length}</span>
                </div>
                <div style={{background:"#fff",borderRadius:12,border:"1.5px solid #e2e8f0",overflow:"hidden"}}>
                  {rows.map((a,i)=>(
                    <div key={a.id} style={{display:"flex",alignItems:"center",gap:12,padding:"9px 14px",borderBottom:i<rows.length-1?"1px solid #f1f5f9":"none"}}>
                      <span style={{fontFamily:"'IBM Plex Mono',monospace",fontWeight:700,color:COA_TYPE_CLR[type],fontSize:".82rem",minWidth:52}}>{a.code}</span>
                      <span style={{flex:1,color:"#0f172a",fontSize:".85rem",fontWeight:500}}>{a.name}</span>
                      {canEdit&&<button onClick={()=>startEdit(a)} style={{background:"none",border:"none",color:"#64748b",cursor:"pointer",fontSize:".78rem",padding:2}} title="Edit">✏</button>}
                      {canEdit&&<button onClick={()=>del(a)} style={{background:"none",border:"none",color:"#ef4444",cursor:"pointer",fontSize:".78rem",padding:2,opacity:.6}} title="Delete">🗑</button>}
                    </div>
                  ))}
                </div>
              </div>
            );
          })}
        </>
      )}
    </div>
  );
}

function AccountReportView({chartOfAccounts=[],exps=[],role}){
  const peso=v=>"₱"+Number(v||0).toLocaleString("en-PH",{minimumFractionDigits:2});
  const years=[...new Set(exps.map(e=>e.year||(e.expDate?Number(e.expDate.slice(0,4)):null)).filter(Boolean))].sort((a,b)=>b-a);
  const[year,setYear]=React.useState("all");
  const inYear=e=>year==="all"||String(e.year||(e.expDate?e.expDate.slice(0,4):""))===String(year);
  const scoped=exps.filter(inYear);
  const totalByCode={};
  let untagged=0;
  scoped.forEach(e=>{
    const amt=Number(e.amount)||0;
    if(e.accountCode){totalByCode[e.accountCode]=(totalByCode[e.accountCode]||0)+amt;}
    else untagged+=amt;
  });
  const codeMeta=Object.fromEntries(chartOfAccounts.map(a=>[String(a.code),a]));
  // Group tagged totals by account type
  const TYPES=["COGS","Expense","Asset","Liability","Equity","Income"];
  const byType={};
  Object.entries(totalByCode).forEach(([code,total])=>{
    const a=codeMeta[code]; const type=a?.type||"Unmapped";
    (byType[type]=byType[type]||[]).push({code,name:a?.name||"(deleted account)",total});
  });
  const grand=Object.values(totalByCode).reduce((s,v)=>s+v,0)+untagged;
  const orderedTypes=[...TYPES.filter(t=>byType[t]),...Object.keys(byType).filter(t=>!TYPES.includes(t))];
  return(
    <div style={{maxWidth:860,margin:"0 auto"}}>
      <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-end",gap:12,marginBottom:14,flexWrap:"wrap"}}>
        <div>
          <h2 style={{margin:"0 0 4px",fontWeight:900,fontSize:"1.4rem",color:"#0f172a",fontFamily:"'Barlow Condensed',sans-serif"}}>📊 Account Report</h2>
          <p style={{margin:0,fontSize:".8rem",color:"#64748b"}}>Expenses totalled by chart-of-accounts code.</p>
        </div>
        <select value={year} onChange={e=>setYear(e.target.value)} style={{border:"1.5px solid #e2e8f0",borderRadius:8,padding:"8px 12px",fontFamily:"inherit",fontSize:".82rem",outline:"none"}}>
          <option value="all">All years</option>
          {years.map(y=><option key={y} value={y}>{y}</option>)}
        </select>
      </div>
      {chartOfAccounts.length===0?(
        <div style={{background:"#fff",borderRadius:14,border:"1.5px dashed #cbd5e1",padding:"40px 24px",textAlign:"center",color:"#64748b",fontSize:".85rem"}}>Load your Chart of Accounts first, then tag expenses to see this report.</div>
      ):(
        <>
          {orderedTypes.length===0&&untagged===0&&<div style={{background:"#fff",borderRadius:14,border:"1.5px dashed #cbd5e1",padding:"40px 24px",textAlign:"center",color:"#64748b",fontSize:".85rem"}}>No tagged expenses yet. Open an expense and pick an Account to populate this report.</div>}
          {orderedTypes.map(type=>{
            const rows=byType[type].sort((a,b)=>String(a.code).localeCompare(String(b.code)));
            const sub=rows.reduce((s,r)=>s+r.total,0);
            const clr=COA_TYPE_CLR[type]||"#64748b";
            return(
              <div key={type} style={{marginBottom:16}}>
                <div style={{display:"flex",alignItems:"center",gap:8,marginBottom:6}}>
                  <span style={{width:10,height:10,borderRadius:3,background:clr}}/>
                  <span style={{fontWeight:800,fontSize:".8rem",textTransform:"uppercase",letterSpacing:".5px",color:"#0f172a"}}>{type}</span>
                </div>
                <div style={{background:"#fff",borderRadius:12,border:"1.5px solid #e2e8f0",overflow:"hidden"}}>
                  {rows.map((r,i)=>(
                    <div key={r.code} style={{display:"flex",alignItems:"center",gap:12,padding:"9px 14px",borderBottom:"1px solid #f1f5f9"}}>
                      <span style={{fontFamily:"'IBM Plex Mono',monospace",fontWeight:700,color:clr,fontSize:".82rem",minWidth:52}}>{r.code}</span>
                      <span style={{flex:1,color:"#0f172a",fontSize:".85rem"}}>{r.name}</span>
                      <span style={{fontWeight:700,color:"#0f172a",fontSize:".85rem",fontFamily:"'IBM Plex Mono',monospace"}}>{peso(r.total)}</span>
                    </div>
                  ))}
                  <div style={{display:"flex",justifyContent:"space-between",padding:"8px 14px",background:clr+"0f",fontWeight:800,fontSize:".82rem",color:clr}}><span>Subtotal — {type}</span><span style={{fontFamily:"'IBM Plex Mono',monospace"}}>{peso(sub)}</span></div>
                </div>
              </div>
            );
          })}
          {untagged>0&&(
            <div style={{background:"#fffbeb",border:"1.5px solid #fde68a",borderRadius:12,padding:"10px 14px",display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:16}}>
              <span style={{fontWeight:700,color:"#92400e",fontSize:".82rem"}}>⚠️ Untagged expenses (no account)</span>
              <span style={{fontWeight:800,color:"#92400e",fontFamily:"'IBM Plex Mono',monospace"}}>{peso(untagged)}</span>
            </div>
          )}
          <div style={{display:"flex",justifyContent:"space-between",padding:"12px 16px",background:"#1e293b",borderRadius:12,alignItems:"center"}}>
            <span style={{fontWeight:800,color:"#f1f5f9",fontSize:".85rem",textTransform:"uppercase",letterSpacing:".5px"}}>Total Expenses</span>
            <span style={{fontWeight:900,color:"#f59e0b",fontSize:"1.1rem",fontFamily:"'Barlow Condensed',sans-serif"}}>{peso(grand)}</span>
          </div>
        </>
      )}
    </div>
  );
}

function BOQHomeView({standaloneBoqs=[],deals=[],session,role,today,onOpenStandalone,onOpenDeal,onNewStandalone,onDeleteStandalone}){
  const peso=v=>"₱"+Number(v||0).toLocaleString("en-PH",{minimumFractionDigits:2});
  const boqTotal=(items=[])=>items.reduce((s,it)=>s+(it.total||0),0);
  // Net of any peso discount (applied before VAT), matching the builder's math.
  const boqNet=(src={})=>{const sub=boqTotal(src.items);const disc=Math.min(Math.max(Number(src.discount)||0,0),sub);return sub-disc;};
  const fmtDate=d=>d?new Date(d+"T00:00:00").toLocaleDateString("en-PH",{year:"numeric",month:"short",day:"numeric"}):"—";
  const[q,setQ]=React.useState("");
  const[picking,setPicking]=React.useState(false);
  const[dq,setDq]=React.useState("");
  let drafts={};
  try{drafts=JSON.parse(localStorage.getItem(KEYS.boqDrafts)||"{}");}catch{}
  // Pipeline-linked BOQs: any deal whose BOQ (Supabase or local draft) actually has content
  const dealEntries=deals.map(d=>{
    const src=d.boqData||drafts[d.id];
    if(!src||!((src.items?.length)||(src.sections?.length))) return null;
    return{kind:"deal",id:d.id,title:src.boqTitle||d.client||"Untitled BOQ",sub:d.ceNo?`${d.client||""} · ${d.ceNo}`:(d.client||""),date:src.boqDate,total:boqNet(src),updatedAt:src.updatedAt||src.boqDate||""};
  }).filter(Boolean);
  const standaloneEntries=standaloneBoqs.map(b=>({kind:"standalone",id:b.id,title:b.title||"Untitled BOQ",sub:b.location||(b.quotationNo?`Quotation ${b.quotationNo}`:"Standalone"),date:b.boqDate,total:boqNet(b),updatedAt:b.updatedAt||b.createdAt||""}));
  const all=[...standaloneEntries,...dealEntries].sort((a,b)=>String(b.updatedAt||"").localeCompare(String(a.updatedAt||"")));
  const ql=q.trim().toLowerCase();
  const filtered=ql?all.filter(e=>e.title.toLowerCase().includes(ql)||(e.sub||"").toLowerCase().includes(ql)):all;
  const canDelete=["Manager","QS"].includes(role);
  return(
    <div style={{maxWidth:980,margin:"0 auto"}}>
      <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-end",gap:12,marginBottom:6,flexWrap:"wrap"}}>
        <div>
          <h2 style={{margin:"0 0 4px",fontWeight:900,fontSize:"1.4rem",color:"#0f172a",fontFamily:"'Barlow Condensed',sans-serif"}}>🧮 Bills of Quantities</h2>
          <p style={{margin:0,fontSize:".8rem",color:"#64748b"}}>Every BOQ belongs to a pipeline deal. Pick a deal to start or edit its BOQ.</p>
        </div>
        <button onClick={()=>{setDq("");setPicking(true);}} style={{background:"#1e293b",border:"none",borderRadius:10,padding:"10px 20px",color:"#fff",fontFamily:"inherit",fontWeight:700,fontSize:".85rem",cursor:"pointer",whiteSpace:"nowrap"}}>＋ New BOQ</button>
      </div>
      <input value={q} onChange={e=>setQ(e.target.value)} placeholder="Search BOQs by name, client, or quotation no…"
        style={{width:"100%",border:"1.5px solid #e2e8f0",borderRadius:9,padding:"9px 13px",fontFamily:"inherit",fontSize:".82rem",color:"#0f172a",boxSizing:"border-box",margin:"14px 0 16px",outline:"none"}}/>
      {filtered.length===0?(
        <div style={{background:"#fff",borderRadius:14,border:"1.5px dashed #cbd5e1",padding:"48px 24px",textAlign:"center"}}>
          <div style={{fontSize:"1.8rem",marginBottom:8}}>🧮</div>
          <div style={{fontWeight:700,color:"#0f172a",fontSize:".95rem",marginBottom:4}}>{all.length===0?"No BOQs yet":"No matches"}</div>
          <div style={{fontSize:".8rem",color:"#64748b",marginBottom:16}}>{all.length===0?"Pick a pipeline deal to create its BOQ.":"Try a different search."}</div>
          {all.length===0&&<button onClick={()=>{setDq("");setPicking(true);}} style={{background:"#1e293b",border:"none",borderRadius:9,padding:"9px 18px",color:"#fff",fontFamily:"inherit",fontWeight:700,fontSize:".82rem",cursor:"pointer"}}>＋ New BOQ</button>}
        </div>
      ):(
        <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(280px,1fr))",gap:12}}>
          {filtered.map(e=>(
            <div key={e.kind+e.id} onClick={()=>e.kind==="standalone"?onOpenStandalone(e.id):onOpenDeal(e.id)}
              style={{background:"#fff",borderRadius:12,border:"1.5px solid #e2e8f0",padding:"14px 16px",cursor:"pointer",transition:"border-color .15s,box-shadow .15s",position:"relative"}}
              onMouseEnter={ev=>{ev.currentTarget.style.borderColor="#94a3b8";ev.currentTarget.style.boxShadow="0 6px 18px rgba(15,23,42,.08)";}}
              onMouseLeave={ev=>{ev.currentTarget.style.borderColor="#e2e8f0";ev.currentTarget.style.boxShadow="none";}}>
              <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",gap:8,marginBottom:8}}>
                <span style={{fontSize:".6rem",fontWeight:800,textTransform:"uppercase",letterSpacing:".5px",padding:"2px 8px",borderRadius:20,background:e.kind==="standalone"?"#f5f3ff":"#eff6ff",color:e.kind==="standalone"?"#7c3aed":"#1d4ed8",border:`1px solid ${e.kind==="standalone"?"#ddd6fe":"#bfdbfe"}`}}>{e.kind==="standalone"?"📄 Standalone":"🔗 Pipeline"}</span>
                {e.kind==="standalone"&&canDelete&&<button onClick={async ev=>{ev.stopPropagation();if((await uiConfirm("Delete this BOQ? This cannot be undone.")))onDeleteStandalone(e.id);}} title="Delete BOQ" style={{background:"none",border:"none",color:"#ef4444",cursor:"pointer",fontSize:".8rem",opacity:.5,padding:0}} onMouseEnter={ev=>ev.currentTarget.style.opacity=1} onMouseLeave={ev=>ev.currentTarget.style.opacity=.5}>🗑</button>}
              </div>
              <div style={{fontWeight:800,color:"#0f172a",fontSize:".95rem",marginBottom:2,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{e.title||"Untitled BOQ"}</div>
              <div style={{fontSize:".72rem",color:"#94a3b8",marginBottom:10,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{e.sub||"—"}</div>
              <div style={{display:"flex",justifyContent:"space-between",alignItems:"center"}}>
                <span style={{fontWeight:800,color:"#059669",fontSize:"1rem",fontFamily:"'Barlow Condensed',sans-serif"}}>{peso(e.total)}</span>
                <span style={{fontSize:".68rem",color:"#94a3b8"}}>{fmtDate(e.date)}</span>
              </div>
            </div>
          ))}
        </div>
      )}
      <Modal open={picking} onClose={()=>setPicking(false)} title="New BOQ — choose its deal">
        <p style={{margin:"0 0 10px",fontSize:".78rem",color:"#64748b"}}>Every BOQ belongs to a deal. Choose the deal this BOQ is for — if it isn't in the pipeline yet, add the deal there first.</p>
        <input value={dq} onChange={e=>setDq(e.target.value)} autoFocus placeholder="Search deals by client, contact, or CE no…"
          style={{width:"100%",border:"1.5px solid #e2e8f0",borderRadius:9,padding:"9px 13px",fontFamily:"inherit",fontSize:".82rem",color:"#0f172a",boxSizing:"border-box",marginBottom:12,outline:"none"}}/>
        {(()=>{
          const s=dq.trim().toLowerCase();
          const pickable=deals
            .filter(d=>!isLostStage(d.stage))
            .filter(d=>!s||(d.client||"").toLowerCase().includes(s)||(d.ceNo||"").toLowerCase().includes(s)||(d.contact||"").toLowerCase().includes(s))
            .sort((a,b)=>String(b.dateAcquired||b.addedAt||"").localeCompare(String(a.dateAcquired||a.addedAt||"")));
          if(!pickable.length) return <div style={{padding:"24px",textAlign:"center",color:"#94a3b8",fontSize:".82rem"}}>No matching deals. Create the deal in the Pipeline first, then come back to build its BOQ.</div>;
          return(
            <div style={{maxHeight:"46vh",overflowY:"auto",display:"flex",flexDirection:"column",gap:6}}>
              {pickable.map(d=>{
                const hasBoq=!!(d.boqData&&((d.boqData.items?.length)||(d.boqData.sections?.length)));
                const parent=d.parentDealId?deals.find(x=>x.id===d.parentDealId):null;
                return(
                  <button key={d.id} onClick={()=>{setPicking(false);onOpenDeal(d.id);}}
                    style={{textAlign:"left",background:d.parentDealId?"#fffbeb":"#f8fafc",border:`1.5px solid ${d.parentDealId?"#fde68a":"#e2e8f0"}`,borderRadius:10,padding:"10px 13px",cursor:"pointer",fontFamily:"inherit"}}
                    onMouseEnter={ev=>ev.currentTarget.style.borderColor="#94a3b8"} onMouseLeave={ev=>ev.currentTarget.style.borderColor=d.parentDealId?"#fde68a":"#e2e8f0"}>
                    {d.parentDealId&&<div style={{fontFamily:"'IBM Plex Mono',monospace",fontSize:".56rem",fontWeight:700,color:"#d97706",letterSpacing:".5px",marginBottom:2}}>↳ ADDENDUM{parent?` OF ${(parent.client||parent.contact||"").toUpperCase()}`:""}</div>}
                    <div style={{fontWeight:700,color:"#0f172a",fontSize:".85rem"}}>{d.client||d.contact||"Untitled deal"}{d.ceNo?` · ${d.ceNo}`:""}</div>
                    <div style={{fontSize:".72rem",color:"#94a3b8",marginTop:2}}>{d.stage||"—"}{hasBoq?" · already has a BOQ":""}</div>
                  </button>
                );
              })}
            </div>
          );
        })()}
      </Modal>
    </div>
  );
}


